CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.queue_contact_birthday_calendar_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.contact_birthday_calendar_events set sync_status='pending', last_error=null
  where contact_id=new.id;
  if new.birth_date is not null and new.broker <> 'unassigned' then
    insert into public.contact_birthday_calendar_events(contact_id,broker)
    values(new.id,new.broker) on conflict(contact_id,broker) do nothing;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.assign_contacts(p_contact_ids uuid[], p_broker broker_assignment)
 RETURNS SETOF contacts
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  update public.contacts
  set
    broker = p_broker,
    google_calendar_sync_status = case
      when next_follow_up_date is not null or google_calendar_event_id is not null
        then 'pending'::public.calendar_sync_status
      else 'synced'::public.calendar_sync_status
    end,
    google_calendar_last_error = null
  where id = any(p_contact_ids)
  returning *;
$function$
CREATE OR REPLACE FUNCTION public.merge_contacts(p_target_id uuid, p_source_id uuid, p_first_name text, p_last_name text, p_phone text, p_email text, p_broker broker_assignment, p_client_type client_type, p_priority contact_priority, p_status contact_status, p_next_follow_up_date date, p_google_event_id text, p_google_event_broker broker_assignment, p_merged_by_user_id uuid)
 RETURNS contacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_source public.contacts;
  v_target public.contacts;
  v_result public.contacts;
  v_last_contact timestamptz;
begin
  if p_target_id = p_source_id then
    raise exception 'Les contacts à fusionner doivent être différents';
  end if;

  select * into v_target from public.contacts where id = p_target_id for update;
  select * into v_source from public.contacts where id = p_source_id for update;
  if v_target.id is null or v_source.id is null then
    raise exception 'Contact de fusion introuvable';
  end if;

  update public.client_notes
  set contact_id = p_target_id
  where contact_id = p_source_id;

  update public.pipeline_history
  set contact_id = p_target_id
  where contact_id = p_source_id;

  select max(created_at) into v_last_contact
  from public.client_notes
  where contact_id = p_target_id;

  update public.contacts
  set
    first_name = trim(p_first_name),
    last_name = trim(p_last_name),
    phone = trim(p_phone),
    email = trim(p_email),
    broker = p_broker,
    client_type = p_client_type,
    priority = p_priority,
    status = p_status,
    last_contact_date = greatest(v_target.last_contact_date, v_source.last_contact_date, v_last_contact),
    next_follow_up_date = p_next_follow_up_date,
    google_calendar_event_id = p_google_event_id,
    google_calendar_event_broker = p_google_event_broker,
    google_calendar_sync_status = case
      when p_next_follow_up_date is null
        then 'synced'::public.calendar_sync_status
      else 'pending'::public.calendar_sync_status
    end,
    google_calendar_last_error = null
  where id = p_target_id
  returning * into v_result;

  insert into public.contact_merges (
    merged_into_contact_id,
    merged_from,
    merged_by_user_id
  ) values (
    p_target_id,
    to_jsonb(v_source),
    p_merged_by_user_id
  );

  delete from public.contacts where id = p_source_id;
  return v_result;
end;
$function$
CREATE OR REPLACE FUNCTION public.update_pipeline_stage(p_contact_id uuid, p_pipeline_type text, p_to_stage text, p_changed_by broker_assignment)
 RETURNS contacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_contact public.contacts;
  v_from_stage text;
begin
  if p_changed_by = 'unassigned' then raise exception 'Courtier invalide'; end if;
  select * into v_contact from public.contacts where id = p_contact_id for update;
  if v_contact.id is null then raise exception 'Contact introuvable'; end if;

  if p_pipeline_type = 'buyer' then
    if v_contact.client_type not in ('buyer', 'buyer_seller')
      or not (p_to_stage = any (array['new', 'qualified', 'search', 'visits', 'offer', 'conditions', 'notary', 'purchased', 'long_term']))
    then raise exception 'Étape acheteur invalide'; end if;
    v_from_stage := v_contact.buyer_pipeline_stage;
    if v_from_stage = p_to_stage then return v_contact; end if;
    update public.contacts set buyer_pipeline_stage = p_to_stage where id = p_contact_id returning * into v_contact;
  elsif p_pipeline_type = 'seller' then
    if v_contact.client_type not in ('seller', 'buyer_seller')
      or not (p_to_stage = any (array['new', 'to_contact', 'evaluation', 'follow_up', 'contract_signed', 'on_market', 'offer_received', 'conditions', 'notary', 'sold', 'long_term']))
    then raise exception 'Étape vendeur invalide'; end if;
    v_from_stage := v_contact.seller_pipeline_stage;
    if v_from_stage = p_to_stage then return v_contact; end if;
    update public.contacts set seller_pipeline_stage = p_to_stage where id = p_contact_id returning * into v_contact;
  else
    raise exception 'Pipeline invalide';
  end if;

  insert into public.pipeline_history (
    contact_id, pipeline_type, from_stage, to_stage, changed_by_broker
  ) values (
    p_contact_id, p_pipeline_type, v_from_stage, p_to_stage, p_changed_by
  );
  return v_contact;
end;
$function$
CREATE OR REPLACE FUNCTION public.normalize_contact_address_part(p_value text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select trim(regexp_replace(lower(unaccent(coalesce(trim(p_value), ''))), '[^a-z0-9]+', ' ', 'g'));
$function$
CREATE OR REPLACE FUNCTION public.normalize_contact_address(p_civic_number text, p_address text, p_apartment text, p_city text, p_province text, p_postal_code text, p_country text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select array_to_string(array[
    public.normalize_contact_address_part(p_civic_number),
    public.normalize_contact_address_part(
      regexp_replace(
        regexp_replace(
          regexp_replace(lower(unaccent(coalesce(trim(p_address), ''))), '\mav\.?\M', 'avenue', 'g'),
          '\mboul\.?\M', 'boulevard', 'g'),
        '\mch\.?\M', 'chemin', 'g')),
    public.normalize_contact_address_part(p_apartment),
    public.normalize_contact_address_part(p_city),
    public.normalize_contact_address_part(p_province),
    replace(public.normalize_contact_address_part(p_postal_code), ' ', ''),
    public.normalize_contact_address_part(p_country)
  ], '|');
$function$
CREATE OR REPLACE FUNCTION public.save_contact_addresses(p_contact_id uuid, p_addresses jsonb)
 RETURNS contacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_item jsonb;
  v_key text;
  v_primary_key text;
  v_kept_keys text[] := array[]::text[];
  v_primary public.contact_addresses;
  v_result public.contacts;
begin
  perform 1 from public.contacts where id = p_contact_id for update;
  if not found then raise exception 'Contact introuvable'; end if;

  update public.contact_addresses set is_primary = false, label = case when label = 'Principale' then 'Ancienne adresse' else label end where contact_id = p_contact_id;

  for v_item in select value from jsonb_array_elements(coalesce(p_addresses, '[]'::jsonb)) loop
    v_key := public.normalize_contact_address(
      v_item->>'civic_number', v_item->>'address', v_item->>'apartment', v_item->>'city',
      v_item->>'province', v_item->>'postal_code', v_item->>'country'
    );
    if replace(v_key, '|', '') = '' or v_key = any(v_kept_keys) then continue; end if;
    v_kept_keys := array_append(v_kept_keys, v_key);
    if coalesce((v_item->>'is_primary')::boolean, false) and v_primary_key is null then v_primary_key := v_key; end if;

    insert into public.contact_addresses (
      contact_id, civic_number, address, apartment, city, province, postal_code, country,
      is_primary, label, normalized_key
    ) values (
      p_contact_id,
      trim(coalesce(v_item->>'civic_number', '')), trim(coalesce(v_item->>'address', '')),
      trim(coalesce(v_item->>'apartment', '')), trim(coalesce(v_item->>'city', '')),
      trim(coalesce(v_item->>'province', '')), trim(coalesce(v_item->>'postal_code', '')),
      trim(coalesce(v_item->>'country', '')), false,
      case when v_item->>'label' = any(array['Ancienne adresse', 'Résidence secondaire', 'Autre']) then v_item->>'label' else 'Ancienne adresse' end,
      v_key
    )
    on conflict (contact_id, normalized_key) do update set
      civic_number = excluded.civic_number, address = excluded.address, apartment = excluded.apartment,
      city = excluded.city, province = excluded.province, postal_code = excluded.postal_code,
      country = excluded.country, label = excluded.label;
  end loop;

  if cardinality(v_kept_keys) = 0 then
    delete from public.contact_addresses where contact_id = p_contact_id;
    update public.contacts set civic_number='', address='', apartment='', city='', province='', postal_code='', country='' where id=p_contact_id returning * into v_result;
    return v_result;
  end if;

  delete from public.contact_addresses where contact_id = p_contact_id and not (normalized_key = any(v_kept_keys));
  v_primary_key := coalesce(v_primary_key, v_kept_keys[1]);
  update public.contact_addresses set
    is_primary = normalized_key = v_primary_key,
    label = case when normalized_key = v_primary_key then 'Principale' when label = 'Principale' then 'Ancienne adresse' else label end
  where contact_id = p_contact_id;

  select * into v_primary from public.contact_addresses where contact_id = p_contact_id and is_primary;
  update public.contacts set
    civic_number=v_primary.civic_number, address=v_primary.address, apartment=v_primary.apartment,
    city=v_primary.city, province=v_primary.province, postal_code=v_primary.postal_code, country=v_primary.country
  where id=p_contact_id returning * into v_result;
  return v_result;
end;
$function$
CREATE OR REPLACE FUNCTION public.import_contacts_with_addresses(p_entries jsonb, p_source contact_source)
 RETURNS SETOF contacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_entry jsonb; v_contact public.contacts;
begin
  for v_entry in select value from jsonb_array_elements(coalesce(p_entries, '[]'::jsonb)) loop
    insert into public.contacts (first_name,last_name,phone,email,birth_date,civic_number,address,apartment,city,province,postal_code,country,broker,source)
    values (
      trim(coalesce(v_entry#>>'{contact,firstName}','')), trim(coalesce(v_entry#>>'{contact,lastName}','')),
      trim(coalesce(v_entry#>>'{contact,phone}','')), trim(coalesce(v_entry#>>'{contact,email}','')),
      nullif(v_entry#>>'{contact,birthDate}','')::date,
      trim(coalesce(v_entry#>>'{contact,civicNumber}','')), trim(coalesce(v_entry#>>'{contact,address}','')),
      trim(coalesce(v_entry#>>'{contact,apartment}','')), trim(coalesce(v_entry#>>'{contact,city}','')),
      trim(coalesce(v_entry#>>'{contact,province}','')), trim(coalesce(v_entry#>>'{contact,postalCode}','')),
      trim(coalesce(v_entry#>>'{contact,country}','')), 'unassigned', p_source
    ) returning * into v_contact;
    if jsonb_array_length(coalesce(v_entry->'addresses','[]'::jsonb)) > 0 then
      select * into v_contact from public.save_contact_addresses(v_contact.id, v_entry->'addresses');
    end if;
    return next v_contact;
  end loop;
end;
$function$
CREATE OR REPLACE FUNCTION public.merge_contacts_with_addresses(p_target_id uuid, p_source_id uuid, p_addresses jsonb, p_first_name text, p_last_name text, p_phone text, p_email text, p_civic_number text, p_address text, p_apartment text, p_city text, p_province text, p_postal_code text, p_country text, p_broker broker_assignment, p_client_type client_type, p_priority contact_priority, p_status contact_status, p_next_follow_up_date date, p_google_event_id text, p_google_event_broker broker_assignment, p_merged_by_user_id uuid)
 RETURNS contacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_source public.contacts; v_target public.contacts; v_result public.contacts; v_last_contact timestamptz; v_addresses jsonb;
begin
  if p_target_id=p_source_id then raise exception 'Les contacts à fusionner doivent être différents'; end if;
  select * into v_target from public.contacts where id=p_target_id for update;
  select * into v_source from public.contacts where id=p_source_id for update;
  if v_target.id is null or v_source.id is null then raise exception 'Contact de fusion introuvable'; end if;

  update public.client_notes set contact_id=p_target_id where contact_id=p_source_id;
  update public.pipeline_history set contact_id=p_target_id where contact_id=p_source_id;
  insert into public.transaction_contacts(transaction_id,contact_id)
    select transaction_id,p_target_id from public.transaction_contacts where contact_id=p_source_id on conflict do nothing;
  delete from public.transaction_contacts where contact_id=p_source_id;
  select max(created_at) into v_last_contact from public.client_notes where contact_id=p_target_id;

  update public.contacts set
    first_name=trim(p_first_name),last_name=trim(p_last_name),phone=trim(p_phone),email=trim(p_email),
    civic_number=trim(p_civic_number),address=trim(p_address),apartment=trim(p_apartment),city=trim(p_city),province=trim(p_province),postal_code=trim(p_postal_code),country=trim(p_country),
    broker=p_broker,client_type=p_client_type,priority=p_priority,status=p_status,
    last_contact_date=greatest(v_target.last_contact_date,v_source.last_contact_date,v_last_contact),
    next_follow_up_date=p_next_follow_up_date,google_calendar_event_id=p_google_event_id,google_calendar_event_broker=p_google_event_broker,
    google_calendar_sync_status=case when p_next_follow_up_date is null then 'synced' else 'pending' end,google_calendar_last_error=null
  where id=p_target_id;

  v_addresses := coalesce(p_addresses,'[]'::jsonb);
  if jsonb_array_length(v_addresses)=0 then
    select coalesce(jsonb_agg(jsonb_build_object(
      'civic_number',civic_number,'address',address,'apartment',apartment,'city',city,'province',province,'postal_code',postal_code,'country',country,
      'is_primary',contact_id=p_target_id and is_primary,'label',case when contact_id=p_target_id and is_primary then 'Principale' else 'Ancienne adresse' end
    ) order by (contact_id=p_target_id and is_primary) desc),'[]'::jsonb) into v_addresses
    from public.contact_addresses where contact_id in (p_target_id,p_source_id);
  end if;
  if jsonb_array_length(v_addresses)>0 then select * into v_result from public.save_contact_addresses(p_target_id,v_addresses); end if;
  insert into public.contact_merges(merged_into_contact_id,merged_from,merged_by_user_id) values(p_target_id,to_jsonb(v_source),p_merged_by_user_id);
  delete from public.contacts where id=p_source_id;
  select * into v_result from public.contacts where id=p_target_id;
  return v_result;
end;
$function$
CREATE OR REPLACE FUNCTION public.enrich_contact_birth_dates(p_updates jsonb)
 RETURNS SETOF contacts
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.contacts as contacts
  set birth_date = updates.birth_date
  from (
    select (item->>'contactId')::uuid as contact_id, nullif(item->>'birthDate','')::date as birth_date
    from jsonb_array_elements(coalesce(p_updates, '[]'::jsonb)) as items(item)
  ) as updates
  where contacts.id = updates.contact_id
    and contacts.birth_date is null
    and updates.birth_date is not null
  returning contacts.*;
$function$
CREATE OR REPLACE FUNCTION public.merge_contacts_with_birthdays(p_target_id uuid, p_source_id uuid, p_addresses jsonb, p_first_name text, p_last_name text, p_phone text, p_email text, p_birth_date date, p_civic_number text, p_address text, p_apartment text, p_city text, p_province text, p_postal_code text, p_country text, p_broker broker_assignment, p_client_type client_type, p_priority contact_priority, p_status contact_status, p_next_follow_up_date date, p_google_event_id text, p_google_event_broker broker_assignment, p_merged_by_user_id uuid)
 RETURNS contacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_result public.contacts;
begin
  select * into v_result from public.merge_contacts_with_addresses(
    p_target_id,p_source_id,p_addresses,p_first_name,p_last_name,p_phone,p_email,
    p_civic_number,p_address,p_apartment,p_city,p_province,p_postal_code,p_country,
    p_broker,p_client_type,p_priority,p_status,p_next_follow_up_date,p_google_event_id,p_google_event_broker,p_merged_by_user_id
  );
  update public.contacts set birth_date=p_birth_date where id=p_target_id returning * into v_result;
  return v_result;
end;
$function$
CREATE OR REPLACE FUNCTION public.queue_contact_mortgage_renewal_calendar_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (tg_op = 'INSERT' and new.mortgage_renewal_date is not null)
     or (tg_op = 'UPDATE' and new.mortgage_renewal_date is distinct from old.mortgage_renewal_date) then
    insert into public.contact_mortgage_renewal_calendar_events(contact_id, broker, sync_status, last_error)
    select new.id, broker, 'pending'::public.calendar_sync_status, null
    from unnest(array['france','maxime','sandrine']::public.broker_assignment[]) as brokers(broker)
    on conflict (contact_id, broker) do update set
      sync_status = 'pending',
      last_error = null,
      updated_at = now();
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.create_listing_with_owners(p_values jsonb, p_owner_contact_ids uuid[])
 RETURNS listings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_listing public.listings;
  v_actor public.broker_assignment;
begin
  v_actor := nullif(p_values->>'actorBroker', '')::public.broker_assignment;
  if v_actor = 'unassigned' then v_actor := null; end if;

  if exists (
    select 1 from unnest(coalesce(p_owner_contact_ids, array[]::uuid[])) as requested(owner_id)
    left join public.contacts as contacts on contacts.id = requested.owner_id
    where contacts.id is null
  ) then
    raise exception 'Propriétaire invalide' using errcode = 'P0001';
  end if;

  insert into public.listings (
    civic_number, address, apartment, city, province, postal_code, country,
    centris_number, broker, status, purpose, asking_price, monthly_rent,
    property_type, listing_date, contract_signed_date, expiration_date, centris_url, public_url,
    primary_image_url, general_notes
  ) values (
    trim(coalesce(p_values->>'civicNumber', '')), trim(coalesce(p_values->>'address', '')),
    trim(coalesce(p_values->>'apartment', '')), trim(coalesce(p_values->>'city', '')),
    trim(coalesce(p_values->>'province', '')), trim(coalesce(p_values->>'postalCode', '')),
    trim(coalesce(p_values->>'country', '')), trim(coalesce(p_values->>'centrisNumber', '')),
    (p_values->>'broker')::public.broker_assignment, p_values->>'status', p_values->>'purpose',
    nullif(p_values->>'askingPrice', '')::numeric, nullif(p_values->>'monthlyRent', '')::numeric,
    p_values->>'propertyType', nullif(p_values->>'listingDate', '')::date, nullif(p_values->>'contractSignedDate', '')::date,
    nullif(p_values->>'expirationDate', '')::date, trim(coalesce(p_values->>'centrisUrl', '')),
    trim(coalesce(p_values->>'publicUrl', '')), trim(coalesce(p_values->>'primaryImageUrl', '')),
    trim(coalesce(p_values->>'generalNotes', ''))
  ) returning * into v_listing;

  insert into public.listing_contacts (listing_id, contact_id, role)
  select v_listing.id, owners.owner_id, 'owner'
  from (select distinct owner_id from unnest(coalesce(p_owner_contact_ids, array[]::uuid[])) as requested(owner_id)) as owners;

  insert into public.listing_marketing_tasks (listing_id, title, task_key, sort_order)
  select v_listing.id, task.title, task.task_key, task.sort_order
  from (values
    ('PHOTOS', 'photos', 10, null::text),
    ('PANCARTE INSTALLÉE', 'sign', 20, null::text),
    ('DOCUMENTS DU PROPRIÉTAIRE', 'documents', 30, null::text),
    ('ACTE DE VENTE', 'owner_deed', 31, null::text),
    ('CERTIFICAT DE LOCALISATION', 'owner_location_certificate', 32, null::text),
    ('REGISTRE FONCIER', 'owner_land_registry', 33, null::text),
    ('RELEVÉ HYPOTHÉCAIRE', 'owner_mortgage_statement', 34, null::text),
    ('CONVENTION D’INDIVISION', 'condo_indivision_agreement', 35, 'condo'),
    ('ASSURANCES', 'condo_insurance', 36, 'condo'),
    ('RENONCIATION DROIT DE PRÉEMPTION', 'condo_preemption_waiver', 37, 'condo'),
    ('DÉCLARATION DE COPROPRIÉTÉ', 'condo_declaration', 38, 'condo'),
    ('POLICE D’ASSURANCE DE LA COPROPRIÉTÉ (DOIT DÉMONTRER LE MONTANT DE TOUTES LES PRIMES)', 'condo_insurance_policy', 39, 'condo'),
    ('ASSEMBLÉE GÉNÉRALE ANNUELLE', 'condo_annual_general_meeting', 40, 'condo'),
    ('PROCÈS-VERBAUX', 'condo_minutes', 41, 'condo'),
    ('ÉTATS FINANCIERS', 'condo_financial_statements', 42, 'condo'),
    ('BUDGETS', 'condo_budgets', 43, 'condo'),
    ('DESCRIPTION DE L’UNITÉ DE RÉFÉRENCE (FINITIONS D’ORIGINES)', 'condo_reference_unit_description', 44, 'condo'),
    ('CERTIFICAT DE PIQUETAGE (S’IL Y A LIEU)', 'land_survey_certificate', 45, 'land'),
    ('UTILISATION DU CCG RECOMMANDÉE', 'land_ccg_recommended', 46, 'land'),
    ('GRILLE DE ZONAGE', 'land_zoning_grid', 47, 'land'),
    ('PUBLICATION CENTRIS', 'centris', 60, null::text),
    ('RÉSEAUX SOCIAUX', 'social_media', 70, null::text),
    ('VISITE LIBRE', 'open_house', 80, null::text),
    ('DRONE', 'video_drone', 90, null::text)
  ) as task(title, task_key, sort_order, property_requirement)
  where task.property_requirement is null or task.property_requirement = v_listing.property_type;

  if v_listing.purpose = 'sale' and v_listing.asking_price is not null then
    insert into public.listing_price_history (listing_id, purpose, amount, changed_by)
    values (v_listing.id, 'sale', v_listing.asking_price, v_actor);
  elsif v_listing.purpose = 'rental' and v_listing.monthly_rent is not null then
    insert into public.listing_price_history (listing_id, purpose, amount, changed_by)
    values (v_listing.id, 'rental', v_listing.monthly_rent, v_actor);
  end if;

  insert into public.listing_activity (listing_id, event_type, title, actor_broker)
  values (v_listing.id, 'listing_created', 'Listing créé', v_actor);
  return v_listing;
end;
$function$
CREATE OR REPLACE FUNCTION public.update_listing_with_owners(p_listing_id uuid, p_values jsonb, p_owner_contact_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS listings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_before public.listings;
  v_listing public.listings;
  v_actor public.broker_assignment;
begin
  v_actor := nullif(p_values->>'actorBroker', '')::public.broker_assignment;
  if v_actor = 'unassigned' then v_actor := null; end if;
  select * into v_before from public.listings where id = p_listing_id for update;
  if not found then raise exception 'Listing introuvable' using errcode = 'P0001'; end if;

  if p_owner_contact_ids is not null and exists (
    select 1 from unnest(p_owner_contact_ids) as requested(owner_id)
    left join public.contacts as contacts on contacts.id = requested.owner_id
    where contacts.id is null
  ) then raise exception 'Propriétaire invalide' using errcode = 'P0001'; end if;

  update public.listings set
    civic_number = case when p_values ? 'civicNumber' then trim(coalesce(p_values->>'civicNumber', '')) else civic_number end,
    address = case when p_values ? 'address' then trim(coalesce(p_values->>'address', '')) else address end,
    apartment = case when p_values ? 'apartment' then trim(coalesce(p_values->>'apartment', '')) else apartment end,
    city = case when p_values ? 'city' then trim(coalesce(p_values->>'city', '')) else city end,
    province = case when p_values ? 'province' then trim(coalesce(p_values->>'province', '')) else province end,
    postal_code = case when p_values ? 'postalCode' then trim(coalesce(p_values->>'postalCode', '')) else postal_code end,
    country = case when p_values ? 'country' then trim(coalesce(p_values->>'country', '')) else country end,
    centris_number = case when p_values ? 'centrisNumber' then trim(coalesce(p_values->>'centrisNumber', '')) else centris_number end,
    broker = case when p_values ? 'broker' then (p_values->>'broker')::public.broker_assignment else broker end,
    status = case when p_values ? 'status' then p_values->>'status' else status end,
    purpose = case when p_values ? 'purpose' then p_values->>'purpose' else purpose end,
    asking_price = case when p_values ? 'askingPrice' then nullif(p_values->>'askingPrice', '')::numeric else asking_price end,
    monthly_rent = case when p_values ? 'monthlyRent' then nullif(p_values->>'monthlyRent', '')::numeric else monthly_rent end,
    property_type = case when p_values ? 'propertyType' then p_values->>'propertyType' else property_type end,
    listing_date = case when p_values ? 'listingDate' then nullif(p_values->>'listingDate', '')::date else listing_date end,
    contract_signed_date = case when p_values ? 'contractSignedDate' then nullif(p_values->>'contractSignedDate', '')::date else contract_signed_date end,
    expiration_date = case when p_values ? 'expirationDate' then nullif(p_values->>'expirationDate', '')::date else expiration_date end,
    centris_url = case when p_values ? 'centrisUrl' then trim(coalesce(p_values->>'centrisUrl', '')) else centris_url end,
    public_url = case when p_values ? 'publicUrl' then trim(coalesce(p_values->>'publicUrl', '')) else public_url end,
    primary_image_url = case when p_values ? 'primaryImageUrl' then trim(coalesce(p_values->>'primaryImageUrl', '')) else primary_image_url end,
    general_notes = case when p_values ? 'generalNotes' then trim(coalesce(p_values->>'generalNotes', '')) else general_notes end
  where id = p_listing_id returning * into v_listing;

  if p_owner_contact_ids is not null then
    delete from public.listing_contacts where listing_id = p_listing_id;
    insert into public.listing_contacts (listing_id, contact_id, role)
    select p_listing_id, owners.owner_id, 'owner'
    from (select distinct owner_id from unnest(p_owner_contact_ids) as requested(owner_id)) as owners;
  end if;

  insert into public.listing_marketing_tasks (listing_id, title, task_key, sort_order)
  select p_listing_id, task.title, task.task_key, task.sort_order
  from (values
    ('PHOTOS', 'photos', 10, null::text),
    ('PANCARTE INSTALLÉE', 'sign', 20, null::text),
    ('DOCUMENTS DU PROPRIÉTAIRE', 'documents', 30, null::text),
    ('ACTE DE VENTE', 'owner_deed', 31, null::text),
    ('CERTIFICAT DE LOCALISATION', 'owner_location_certificate', 32, null::text),
    ('REGISTRE FONCIER', 'owner_land_registry', 33, null::text),
    ('RELEVÉ HYPOTHÉCAIRE', 'owner_mortgage_statement', 34, null::text),
    ('CONVENTION D’INDIVISION', 'condo_indivision_agreement', 35, 'condo'),
    ('ASSURANCES', 'condo_insurance', 36, 'condo'),
    ('RENONCIATION DROIT DE PRÉEMPTION', 'condo_preemption_waiver', 37, 'condo'),
    ('DÉCLARATION DE COPROPRIÉTÉ', 'condo_declaration', 38, 'condo'),
    ('POLICE D’ASSURANCE DE LA COPROPRIÉTÉ (DOIT DÉMONTRER LE MONTANT DE TOUTES LES PRIMES)', 'condo_insurance_policy', 39, 'condo'),
    ('ASSEMBLÉE GÉNÉRALE ANNUELLE', 'condo_annual_general_meeting', 40, 'condo'),
    ('PROCÈS-VERBAUX', 'condo_minutes', 41, 'condo'),
    ('ÉTATS FINANCIERS', 'condo_financial_statements', 42, 'condo'),
    ('BUDGETS', 'condo_budgets', 43, 'condo'),
    ('DESCRIPTION DE L’UNITÉ DE RÉFÉRENCE (FINITIONS D’ORIGINES)', 'condo_reference_unit_description', 44, 'condo'),
    ('CERTIFICAT DE PIQUETAGE (S’IL Y A LIEU)', 'land_survey_certificate', 45, 'land'),
    ('UTILISATION DU CCG RECOMMANDÉE', 'land_ccg_recommended', 46, 'land'),
    ('GRILLE DE ZONAGE', 'land_zoning_grid', 47, 'land'),
    ('PUBLICATION CENTRIS', 'centris', 60, null::text),
    ('RÉSEAUX SOCIAUX', 'social_media', 70, null::text),
    ('VISITE LIBRE', 'open_house', 80, null::text),
    ('DRONE', 'video_drone', 90, null::text)
  ) as task(title, task_key, sort_order, property_requirement)
  where task.property_requirement is null or task.property_requirement = v_listing.property_type
  on conflict (listing_id, task_key) where task_key is not null do nothing;

  if v_before.purpose is distinct from v_listing.purpose then
    insert into public.listing_activity (listing_id, event_type, title, detail, actor_broker)
    values (p_listing_id, 'purpose_changed', 'Type de mandat modifié', v_before.purpose || ' → ' || v_listing.purpose, v_actor);
  end if;
  if v_before.status is distinct from v_listing.status then
    insert into public.listing_activity (listing_id, event_type, title, detail, actor_broker)
    values (p_listing_id, 'status_changed', 'Statut modifié', v_before.status || ' → ' || v_listing.status, v_actor);
  end if;
  if v_before.broker is distinct from v_listing.broker then
    insert into public.listing_activity (listing_id, event_type, title, detail, actor_broker)
    values (p_listing_id, 'broker_changed', 'Courtier responsable modifié', v_before.broker || ' → ' || v_listing.broker, v_actor);
  end if;
  if v_before.general_notes is distinct from v_listing.general_notes then
    insert into public.listing_activity (listing_id, event_type, title, actor_broker)
    values (p_listing_id, 'note_updated', 'Notes internes mises à jour', v_actor);
  end if;

  if v_listing.purpose = 'sale' and v_listing.asking_price is not null
    and (v_before.purpose is distinct from 'sale' or v_before.asking_price is distinct from v_listing.asking_price) then
    insert into public.listing_price_history (listing_id, purpose, amount, changed_by)
    values (p_listing_id, 'sale', v_listing.asking_price, v_actor);
    insert into public.listing_activity (listing_id, event_type, title, detail, actor_broker, metadata)
    values (p_listing_id, 'price_changed', 'Prix demandé modifié',
      coalesce(v_before.asking_price::text, '—') || ' → ' || v_listing.asking_price::text, v_actor,
      jsonb_build_object('before', v_before.asking_price, 'after', v_listing.asking_price));
  elsif v_listing.purpose = 'rental' and v_listing.monthly_rent is not null
    and (v_before.purpose is distinct from 'rental' or v_before.monthly_rent is distinct from v_listing.monthly_rent) then
    insert into public.listing_price_history (listing_id, purpose, amount, changed_by)
    values (p_listing_id, 'rental', v_listing.monthly_rent, v_actor);
    insert into public.listing_activity (listing_id, event_type, title, detail, actor_broker, metadata)
    values (p_listing_id, 'rent_changed', 'Loyer mensuel modifié',
      coalesce(v_before.monthly_rent::text, '—') || ' → ' || v_listing.monthly_rent::text, v_actor,
      jsonb_build_object('before', v_before.monthly_rent, 'after', v_listing.monthly_rent));
  end if;
  return v_listing;
end;
$function$
CREATE OR REPLACE FUNCTION public.set_listing_marketing_task_completion(p_listing_id uuid, p_task_id uuid, p_completed boolean, p_actor broker_assignment DEFAULT NULL::broker_assignment)
 RETURNS listing_marketing_tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_task public.listing_marketing_tasks;
begin
  if p_actor = 'unassigned' then p_actor := null; end if;
  update public.listing_marketing_tasks set completed = p_completed,
    completed_at = case when p_completed then now() else null end,
    completed_by = case when p_completed then p_actor else null end
  where id = p_task_id and listing_id = p_listing_id returning * into v_task;
  if not found then raise exception 'Tâche introuvable' using errcode = 'P0001'; end if;
  insert into public.listing_activity (listing_id, event_type, title, actor_broker)
  values (p_listing_id, case when p_completed then 'marketing_task_completed' else 'marketing_task_reopened' end,
    v_task.title || case when p_completed then ' complétée' else ' rouverte' end, p_actor);
  return v_task;
end; $function$
