CREATE OR REPLACE FUNCTION public.update_custom_listing_marketing_task(p_listing_id uuid, p_task_id uuid, p_title text, p_actor broker_assignment DEFAULT NULL::broker_assignment)
 RETURNS listing_marketing_tasks
 LANGUAGE plpgsql
