CREATE OR REPLACE FUNCTION public.create_listing_visit(p_listing_id uuid, p_values jsonb, p_actor broker_assignment DEFAULT NULL::broker_assignment)
 RETURNS listing_visits
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_visit public.listing_visits;
begin
  if p_actor = 'unassigned' then p_actor := null; end if;
  insert into public.listing_visits (listing_id, visit_date, visit_time, visiting_broker_name,
