CREATE OR REPLACE FUNCTION public.create_listing_offer(p_listing_id uuid, p_values jsonb, p_actor broker_assignment DEFAULT NULL::broker_assignment)
 RETURNS listing_offers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_listing public.listings;
  v_offer public.listing_offers;
begin
  if p_actor = 'unassigned' then p_actor := null; end if;
  select * into v_listing from public.listings where id = p_listing_id for update;
  if not found then raise exception 'Listing introuvable' using errcode = 'P0001'; end if;

  insert into public.listing_offers (
    listing_id, purpose, offer_date, amount, status, buyer_names,
    collaborating_broker_name, collaborating_broker_agency, notes, accepted_at, created_by
  ) values (
    p_listing_id, v_listing.purpose, (p_values->>'offerDate')::date,
    (p_values->>'amount')::numeric, p_values->>'status',
    trim(coalesce(p_values->>'buyerNames', '')),
    trim(coalesce(p_values->>'collaboratingBrokerName', '')),
    trim(coalesce(p_values->>'collaboratingBrokerAgency', '')),
    trim(coalesce(p_values->>'notes', '')),
    case when p_values->>'status' = 'accepted' then now() else null end,
    p_actor
  ) returning * into v_offer;

  if v_listing.status = 'active' then
    update public.listings
    set status = case when v_offer.status = 'accepted' then 'conditional' else 'offer_received' end
    where id = p_listing_id;
  elsif v_listing.status = 'offer_received' and v_offer.status = 'accepted' then
    update public.listings set status = 'conditional' where id = p_listing_id;
  end if;

  insert into public.listing_activity (listing_id, event_type, title, detail, actor_broker, metadata)
  values (p_listing_id, 'offer_added', 'Offre reçue', v_offer.amount::text, p_actor,
    jsonb_build_object('offerId', v_offer.id, 'status', v_offer.status, 'amount', v_offer.amount));
  return v_offer;
end;
$function$
CREATE OR REPLACE FUNCTION public.update_listing_offer(p_listing_id uuid, p_offer_id uuid, p_values jsonb, p_actor broker_assignment DEFAULT NULL::broker_assignment)
 RETURNS listing_offers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_listing public.listings;
  v_before public.listing_offers;
  v_offer public.listing_offers;
begin
  if p_actor = 'unassigned' then p_actor := null; end if;
  select * into v_listing from public.listings where id = p_listing_id for update;
  if not found then raise exception 'Listing introuvable' using errcode = 'P0001'; end if;
  select * into v_before from public.listing_offers
  where id = p_offer_id and listing_id = p_listing_id for update;
  if not found then raise exception 'Offre introuvable' using errcode = 'P0001'; end if;

  update public.listing_offers set
    offer_date = (p_values->>'offerDate')::date,
    amount = (p_values->>'amount')::numeric,
    status = p_values->>'status',
    buyer_names = trim(coalesce(p_values->>'buyerNames', '')),
    collaborating_broker_name = trim(coalesce(p_values->>'collaboratingBrokerName', '')),
    collaborating_broker_agency = trim(coalesce(p_values->>'collaboratingBrokerAgency', '')),
    notes = trim(coalesce(p_values->>'notes', '')),
    accepted_at = case
      when accepted_at is not null then accepted_at
      when p_values->>'status' = 'accepted' then now()
      else null
    end
  where id = p_offer_id and listing_id = p_listing_id returning * into v_offer;

  if v_listing.status = 'active' then
    update public.listings
    set status = case when v_offer.status = 'accepted' then 'conditional' else 'offer_received' end
    where id = p_listing_id;
  elsif v_listing.status = 'offer_received' and v_offer.status = 'accepted' then
    update public.listings set status = 'conditional' where id = p_listing_id;
  end if;

  insert into public.listing_activity (listing_id, event_type, title, detail, actor_broker, metadata)
  values (p_listing_id, 'offer_updated', 'Offre modifiée', v_offer.amount::text, p_actor,
    jsonb_build_object('offerId', v_offer.id, 'status', v_offer.status, 'amount', v_offer.amount));
  if v_before.status is distinct from v_offer.status then
    insert into public.listing_activity (listing_id, event_type, title, detail, actor_broker, metadata)
    values (p_listing_id, 'offer_status_changed', 'Statut de l’offre modifié',
      v_before.status || ' → ' || v_offer.status, p_actor,
      jsonb_build_object('offerId', v_offer.id, 'before', v_before.status, 'after', v_offer.status));
  end if;
  return v_offer;
end;
$function$
CREATE OR REPLACE FUNCTION public.delete_listing_offer(p_listing_id uuid, p_offer_id uuid, p_actor broker_assignment DEFAULT NULL::broker_assignment)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_offer public.listing_offers;
begin
  if p_actor = 'unassigned' then p_actor := null; end if;
  if exists (select 1 from public.listing_transaction_links where offer_id = p_offer_id) then
    raise exception 'Offre liée à une transaction' using errcode = 'P0001';
  end if;
  delete from public.listing_offers
  where id = p_offer_id and listing_id = p_listing_id returning * into v_offer;
  if not found then raise exception 'Offre introuvable' using errcode = 'P0001'; end if;
  insert into public.listing_activity (listing_id, event_type, title, detail, actor_broker, metadata)
  values (p_listing_id, 'offer_deleted', 'Offre supprimée', v_offer.amount::text, p_actor,
    jsonb_build_object('offerId', v_offer.id, 'status', v_offer.status, 'amount', v_offer.amount));
  return p_offer_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.notify_google_calendar_change(p_channel_id text, p_resource_id text, p_resource_state text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_change_version bigint;
begin
  if p_resource_state not in ('sync', 'exists', 'not_exists') then
    return null;
  end if;

  update public.google_calendar_watch_channels
  set
    resource_id = case
      when resource_id is null and p_resource_state = 'sync' then p_resource_id
      else resource_id
    end,
    change_version = change_version + case
      when p_resource_state in ('exists', 'not_exists') then 1
      else 0
    end,
    last_notification_at = now(),
    last_resource_state = p_resource_state
  where channel_id = p_channel_id
    and (
      resource_id = p_resource_id
      or (resource_id is null and p_resource_state = 'sync')
    )
  returning change_version into v_change_version;

  return v_change_version;
end;
$function$
CREATE OR REPLACE FUNCTION public.complete_listing_sale(p_listing_id uuid, p_sold_price numeric, p_notary_date date, p_collaborating_broker_name text, p_no_collaborating_broker boolean, p_actor_broker broker_assignment)
 RETURNS listings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_before public.listings;
  v_listing public.listings;
  v_actor public.broker_assignment;
  v_collaborating_broker_name text;
begin
  if p_sold_price is null or p_sold_price <= 0 then
    raise exception 'Prix vendu invalide.' using errcode = 'P0001';
  end if;
  if p_notary_date is null then
    raise exception 'Date du notaire requise.' using errcode = 'P0001';
  end if;
  if p_no_collaborating_broker is null then
    raise exception 'Choix du courtier collaborateur requis.' using errcode = 'P0001';
  end if;

  v_collaborating_broker_name := trim(coalesce(p_collaborating_broker_name, ''));
  if not p_no_collaborating_broker and v_collaborating_broker_name = '' then
    raise exception 'Courtier collaborateur requis.' using errcode = 'P0001';
  end if;
  if length(v_collaborating_broker_name) > 240 then
    raise exception 'Courtier collaborateur invalide.' using errcode = 'P0001';
  end if;
  if p_no_collaborating_broker then
    v_collaborating_broker_name := '';
  end if;

  v_actor := p_actor_broker;
  if v_actor = 'unassigned' then v_actor := null; end if;

  select * into v_before
  from public.listings
  where id = p_listing_id
  for update;

  if not found then
    raise exception 'Listing introuvable.' using errcode = 'P0001';
  end if;
  if v_before.purpose <> 'sale' then
    raise exception 'Seul un Listing en vente peut être marqué comme vendu.' using errcode = 'P0001';
  end if;
  if v_before.status = 'sold' then
    raise exception 'Ce Listing est déjà marqué comme vendu.' using errcode = 'P0001';
  end if;

  update public.listings
  set
    sold_price = p_sold_price,
    notary_date = p_notary_date,
    collaborating_broker_name = v_collaborating_broker_name,
    status = 'sold'
  where id = p_listing_id
  returning * into v_listing;

  insert into public.listing_activity (
    listing_id, event_type, title, detail, actor_broker, metadata
  ) values (
    p_listing_id,
    'sale_completed',
    'Listing vendu',
    'Vendu ' || p_sold_price::text || ' $ · Notaire ' || p_notary_date::text
      || ' · Courtier collaborateur : '
      || case when v_collaborating_broker_name = '' then 'Aucun' else v_collaborating_broker_name end,
    v_actor,
    jsonb_build_object(
      'soldPrice', p_sold_price,
      'notaryDate', p_notary_date,
      'collaboratingBrokerName', v_collaborating_broker_name
    )
  );

  insert into public.listing_activity (
    listing_id, event_type, title, detail, actor_broker, metadata
  ) values (
    p_listing_id,
    'status_changed',
    'Statut modifié',
    v_before.status || ' → sold',
    v_actor,
    jsonb_build_object('before', v_before.status, 'after', 'sold')
  );

  return v_listing;
end;
$function$
CREATE OR REPLACE FUNCTION public.delete_contact_note(p_note_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_note public.client_notes;
  v_contact public.contacts;
  v_last_contact_date timestamptz;
begin
  select * into v_note
  from public.client_notes
  where id = p_note_id
  for update;

  if not found then
    raise exception 'Note introuvable.' using errcode = 'P0002';
  end if;

  select * into v_contact
  from public.contacts
  where id = v_note.contact_id
  for update;

  if not found then
    raise exception 'Contact introuvable.' using errcode = 'P0002';
  end if;

  delete from public.client_notes
  where id = p_note_id;

  select max(created_at) into v_last_contact_date
  from public.client_notes
  where contact_id = v_note.contact_id;

  update public.contacts
  set last_contact_date = v_last_contact_date
  where id = v_note.contact_id;

  return jsonb_build_object(
    'noteId', v_note.id,
    'contactId', v_note.contact_id,
    'lastContactDate', v_last_contact_date
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.return_listing_transaction_to_market(p_transaction_id uuid, p_actor_broker broker_assignment DEFAULT NULL::broker_assignment)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_transaction public.transactions;
  v_listing public.listings;
  v_link record;
begin
  if p_actor_broker = 'unassigned' then p_actor_broker := null; end if;

  select * into v_transaction
  from public.transactions
  where id = p_transaction_id
  for update;
  if not found then
    raise exception 'Transaction introuvable.' using errcode = 'P0001';
  end if;
  if v_transaction.type <> 'sale' then
    raise exception 'Seule une Transaction de vente peut revenir sur le marché.' using errcode = 'P0001';
  end if;
  if v_transaction.sale_finalized_at is not null then
    raise exception 'Une vente finalisée ne peut pas revenir sur le marché.' using errcode = 'P0001';
  end if;
  if v_transaction.status = 'cancelled' then
    raise exception 'Cette Transaction est déjà annulée.' using errcode = 'P0001';
  end if;

  select * into v_link
  from public.listing_transaction_links
  where transaction_id = p_transaction_id;
  if not found then
    raise exception 'Cette Transaction ne provient pas d’un Listing.' using errcode = 'P0001';
  end if;

  select * into v_listing
  from public.listings
  where id = v_link.listing_id
  for update;
  if not found then
    raise exception 'Listing introuvable.' using errcode = 'P0001';
  end if;
  if v_listing.status = 'sold' then
    raise exception 'Un Listing vendu ne peut pas revenir sur le marché.' using errcode = 'P0001';
  end if;

  update public.transactions
  set status = 'cancelled'
  where id = p_transaction_id;

  update public.listings
  set status = 'active'
  where id = v_link.listing_id;

  insert into public.listing_activity (
    listing_id, event_type, title, detail, actor_broker, metadata
  ) values (
    v_link.listing_id,
    'returned_to_market',
    'Retour sur le marché',
    'Transaction annulée · propriété remise en marché',
    p_actor_broker,
    jsonb_build_object('transactionId', p_transaction_id, 'offerId', v_link.offer_id)
  );

  return jsonb_build_object(
    'transactionId', p_transaction_id,
    'listingId', v_link.listing_id,
    'offerId', v_link.offer_id
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.create_transaction_from_listing_offer(p_listing_id uuid, p_offer_id uuid, p_actor broker_assignment DEFAULT NULL::broker_assignment)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_listing public.listings;
  v_offer public.listing_offers;
  v_existing uuid;
  v_transaction_id uuid;
  v_address text;
begin
  if p_actor = 'unassigned' then p_actor := null; end if;

  select transaction_id into v_existing
  from public.listing_transaction_links
  where offer_id = p_offer_id;
  if found then return v_existing; end if;

  select * into v_listing
  from public.listings
  where id = p_listing_id
  for update;
  if not found then
    raise exception 'Listing introuvable' using errcode = 'P0001';
  end if;

  select * into v_offer
  from public.listing_offers
  where id = p_offer_id and listing_id = p_listing_id
  for update;
  if not found then
    raise exception 'Offre introuvable' using errcode = 'P0001';
  end if;
  if v_listing.purpose <> 'sale' or v_offer.purpose <> 'sale' then
    raise exception 'Seule une offre de vente peut créer une transaction' using errcode = 'P0001';
  end if;
  if v_offer.status <> 'accepted' then
    raise exception 'L’offre doit être acceptée' using errcode = 'P0001';
  end if;

  select l.transaction_id into v_existing
  from public.listing_transaction_links l
  join public.transactions t on t.id = l.transaction_id
  where l.listing_id = p_listing_id
    and t.status <> 'cancelled'
  order by l.created_at desc, l.transaction_id desc
  limit 1;
  if found then
    raise exception 'Ce Listing possède déjà une transaction active' using errcode = 'P0001';
  end if;

  v_address := concat_ws(', ',
    nullif(trim(concat_ws(' ', nullif(trim(v_listing.civic_number), ''), nullif(trim(v_listing.address), ''))), ''),
    case when trim(v_listing.apartment) <> '' then 'app. ' || trim(v_listing.apartment) end,
    nullif(trim(v_listing.city), ''),
    nullif(trim(concat_ws(' ', nullif(trim(v_listing.province), ''), nullif(trim(v_listing.postal_code), ''))), ''),
    nullif(trim(v_listing.country), '')
  );

  insert into public.transactions (
    address, centris_number, type, broker, price, promise_date, status, general_notes
  ) values (
    v_address, v_listing.centris_number, 'sale', v_listing.broker, v_offer.amount,
    v_offer.offer_date, 'pa_accepted',
    'Créée depuis le Listing ' || v_address || E'\nMontant accepté : ' || v_offer.amount::text
      || case when trim(v_offer.buyer_names) <> '' then E'\nAcheteurs : ' || trim(v_offer.buyer_names) else '' end
  ) returning id into v_transaction_id;

  insert into public.transaction_contacts (transaction_id, contact_id)
  select v_transaction_id, contact_id
  from public.listing_contacts
  where listing_id = p_listing_id and role = 'owner'
  on conflict do nothing;

  insert into public.listing_transaction_links (listing_id, offer_id, transaction_id)
  values (p_listing_id, p_offer_id, v_transaction_id);

  insert into public.listing_activity (listing_id, event_type, title, detail, actor_broker, metadata)
  values (
    p_listing_id,
    'transaction_created',
    'Transaction créée depuis l’offre acceptée',
    v_offer.amount::text,
    p_actor,
    jsonb_build_object('offerId', p_offer_id, 'transactionId', v_transaction_id)
  );

  return v_transaction_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.complete_transaction_purchase(p_transaction_id uuid, p_purchase_price numeric, p_notary_date date, p_collaborating_broker_name text)
 RETURNS transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_transaction public.transactions;
begin
  select * into v_transaction
  from public.transactions
  where id = p_transaction_id
  for update;

  if not found then
    raise exception 'Transaction introuvable.' using errcode = 'P0001';
  end if;
  if v_transaction.type <> 'purchase' then
    raise exception 'Seule une Transaction d''achat peut être finalisée.' using errcode = 'P0001';
  end if;
  if v_transaction.status = 'cancelled' then
    raise exception 'Une Transaction annulée ne peut pas être finalisée.' using errcode = 'P0001';
  end if;
  if v_transaction.purchase_finalized_at is not null then
    raise exception 'Cet achat est déjà finalisé.' using errcode = 'P0001';
  end if;
  if p_purchase_price is null or p_purchase_price <= 0 then
    raise exception 'Prix d''achat final invalide.' using errcode = 'P0001';
  end if;
  if p_notary_date is null then
    raise exception 'Date du notaire requise.' using errcode = 'P0001';
  end if;
  if p_collaborating_broker_name is null or char_length(trim(p_collaborating_broker_name)) > 240 then
    raise exception 'Courtier collaborateur invalide.' using errcode = 'P0001';
  end if;

  update public.transactions
  set
    price = p_purchase_price,
    notary_date = p_notary_date,
    collaborating_broker_name = trim(p_collaborating_broker_name),
    purchase_finalized_at = now()
  where id = p_transaction_id
  returning * into v_transaction;

  return v_transaction;
end;
$function$
CREATE OR REPLACE FUNCTION public.protect_finalized_transaction_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if (old.type = 'sale' and old.sale_finalized_at is not null)
    or (old.type = 'purchase' and old.purchase_finalized_at is not null) then
    if tg_op = 'DELETE' then
      raise exception 'Une transaction finalisée doit être conservée dans l’historique.' using errcode = 'P0001';
    end if;
    raise exception 'Une transaction finalisée ne peut plus être modifiée.' using errcode = 'P0001';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.protect_finalized_listing_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.status in ('sold', 'rented') then
    if tg_op = 'DELETE' then
      raise exception 'Un Listing finalisé doit être conservé dans l’historique.' using errcode = 'P0001';
    end if;
    raise exception 'Un Listing finalisé ne peut plus être modifié.' using errcode = 'P0001';
  end if;

  if tg_op = 'DELETE' and exists (
    select 1
    from public.listing_transaction_links as link
    where link.listing_id = old.id
  ) then
    raise exception 'Ce Listing possède un historique de Transaction et ne peut pas être supprimé.' using errcode = 'P0001';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.protect_finalized_transaction_contacts()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_transaction public.transactions;
begin
  -- FK cascade runs after the parent contact is gone; direct edits stay locked.
  if tg_op = 'DELETE' and not exists (select 1 from public.contacts where id = old.contact_id) then
    return old;
  end if;
  if tg_op in ('UPDATE', 'DELETE') then
    select * into v_transaction from public.transactions where id = old.transaction_id;
    if found and (
      (v_transaction.type = 'sale' and v_transaction.sale_finalized_at is not null)
      or (v_transaction.type = 'purchase' and v_transaction.purchase_finalized_at is not null)
    ) then
      raise exception 'Une transaction finalisée ne peut plus être modifiée.' using errcode = 'P0001';
    end if;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    select * into v_transaction from public.transactions where id = new.transaction_id;
    if found and (
      (v_transaction.type = 'sale' and v_transaction.sale_finalized_at is not null)
      or (v_transaction.type = 'purchase' and v_transaction.purchase_finalized_at is not null)
    ) then
      raise exception 'Une transaction finalisée ne peut plus être modifiée.' using errcode = 'P0001';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.complete_transaction_sale(p_transaction_id uuid, p_sold_price numeric, p_notary_date date, p_collaborating_broker_name text, p_no_collaborating_broker boolean)
 RETURNS transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_transaction public.transactions;
  v_listing public.listings;
  v_listing_id uuid;
  v_offer_id uuid;
  v_collaborating_broker_name text;
begin
  select * into v_transaction
  from public.transactions
  where id = p_transaction_id
  for update;

  if not found then
    raise exception 'Transaction introuvable.' using errcode = 'P0001';
  end if;
  if v_transaction.type <> 'sale' then
    raise exception 'Seule une Transaction de vente peut être finalisée comme vendue.' using errcode = 'P0001';
  end if;
  if v_transaction.status = 'cancelled' then
    raise exception 'Une Transaction annulée ne peut pas être finalisée.' using errcode = 'P0001';
  end if;
  if v_transaction.sale_finalized_at is not null then
    raise exception 'Cette vente est déjà finalisée.' using errcode = 'P0001';
  end if;
  if p_sold_price is null or p_sold_price <= 0 then
    raise exception 'Prix vendu invalide.' using errcode = 'P0001';
  end if;
  if p_notary_date is null then
    raise exception 'Date du notaire requise.' using errcode = 'P0001';
  end if;
  if p_no_collaborating_broker is null then
    raise exception 'Choix du courtier collaborateur requis.' using errcode = 'P0001';
  end if;

  v_collaborating_broker_name := trim(coalesce(p_collaborating_broker_name, ''));
  if not p_no_collaborating_broker and v_collaborating_broker_name = '' then
    raise exception 'Courtier collaborateur requis.' using errcode = 'P0001';
  end if;
  if length(v_collaborating_broker_name) > 240 then
    raise exception 'Courtier collaborateur invalide.' using errcode = 'P0001';
  end if;
  if p_no_collaborating_broker then
    v_collaborating_broker_name := '';
  end if;

  select link.listing_id, link.offer_id
  into v_listing_id, v_offer_id
  from public.listing_transaction_links as link
  where link.transaction_id = p_transaction_id;

  if v_listing_id is not null then
    select * into v_listing
    from public.listings
    where id = v_listing_id
    for update;

    if not found then
      raise exception 'Listing source introuvable.' using errcode = 'P0001';
    end if;
    if v_listing.purpose <> 'sale' then
      raise exception 'Le Listing source n''est pas un mandat de vente.' using errcode = 'P0001';
    end if;
    if v_listing.status in ('sold', 'rented') then
      raise exception 'Le Listing source est déjà finalisé.' using errcode = 'P0001';
    end if;
  end if;

  update public.transactions
  set
    sold_price = p_sold_price,
    notary_date = p_notary_date,
    collaborating_broker_name = v_collaborating_broker_name,
    sale_finalized_at = now()
  where id = p_transaction_id
  returning * into v_transaction;

  if v_listing_id is not null then
    update public.listings
    set
      sold_price = p_sold_price,
      notary_date = p_notary_date,
      collaborating_broker_name = v_collaborating_broker_name,
      status = 'sold'
    where id = v_listing_id;

    insert into public.listing_activity (
      listing_id, event_type, title, detail, actor_broker, metadata
    ) values (
      v_listing_id,
      'sale_completed',
      'Listing vendu',
      'Vendu ' || p_sold_price::text || ' $ · Notaire ' || p_notary_date::text
        || ' · Courtier collaborateur : '
        || case when v_collaborating_broker_name = '' then 'Aucun' else v_collaborating_broker_name end,
      v_transaction.broker,
      jsonb_build_object(
        'transactionId', p_transaction_id,
        'offerId', v_offer_id,
        'soldPrice', p_sold_price,
        'notaryDate', p_notary_date,
        'collaboratingBrokerName', v_collaborating_broker_name
      )
    );

    insert into public.listing_activity (
      listing_id, event_type, title, detail, actor_broker, metadata
    ) values (
      v_listing_id,
      'status_changed',
      'Statut modifié',
      v_listing.status || ' → sold',
      v_transaction.broker,
      jsonb_build_object(
        'transactionId', p_transaction_id,
        'before', v_listing.status,
        'after', 'sold'
      )
    );
  end if;

  return v_transaction;
end;
$function$
CREATE OR REPLACE FUNCTION public.create_transaction_with_contacts(p_values jsonb, p_contact_ids uuid[], p_creation_key uuid)
 RETURNS transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_transaction public.transactions;
begin
  if p_creation_key is null then
    raise exception 'Clé de création requise.' using errcode = 'P0001';
  end if;

  select * into v_transaction
  from public.transactions
  where creation_key = p_creation_key;
  if found then
    return v_transaction;
  end if;

  if p_values is null or jsonb_typeof(p_values) <> 'object' then
    raise exception 'Valeurs de Transaction invalides.' using errcode = 'P0001';
  end if;
  if exists (
    select 1
    from jsonb_object_keys(p_values) as supplied(field_name)
    where supplied.field_name not in (
      'address', 'centris_number', 'type', 'broker', 'price',
      'promise_date', 'status', 'general_notes'
    )
  ) then
    raise exception 'Champ de Transaction non autorisé.' using errcode = 'P0001';
  end if;
  if not (p_values ? 'address')
    or jsonb_typeof(p_values->'address') <> 'string'
    or length(trim(p_values->>'address')) = 0 then
    raise exception 'Adresse de Transaction invalide.' using errcode = 'P0001';
  end if;
  if not (p_values ? 'type') or p_values->>'type' not in ('purchase', 'sale') then
    raise exception 'Type de Transaction invalide.' using errcode = 'P0001';
  end if;
  if not (p_values ? 'broker')
    or p_values->>'broker' not in ('france', 'maxime', 'sandrine') then
    raise exception 'Courtier de Transaction invalide.' using errcode = 'P0001';
  end if;
  if not (p_values ? 'status') or p_values->>'status' not in (
    'new', 'pa_preparation', 'pa_sent', 'pa_accepted', 'inspection',
    'financing', 'other_conditions', 'conditions_met', 'notary',
    'completed', 'cancelled', 'on_market', 'offer_received', 'negotiation'
  ) then
    raise exception 'Statut de Transaction invalide.' using errcode = 'P0001';
  end if;
  if p_values ? 'price' and jsonb_typeof(p_values->'price') not in ('number', 'null') then
    raise exception 'Prix de Transaction invalide.' using errcode = 'P0001';
  end if;
  if p_values ? 'promise_date'
    and jsonb_typeof(p_values->'promise_date') not in ('string', 'null') then
    raise exception 'Date de promesse invalide.' using errcode = 'P0001';
  end if;
  if exists (
    select 1
    from (
      select distinct requested.contact_id
      from unnest(coalesce(p_contact_ids, array[]::uuid[])) as requested(contact_id)
    ) as requested
    left join public.contacts as contact on contact.id = requested.contact_id
    where requested.contact_id is null or contact.id is null
  ) then
    raise exception 'Contact lié invalide.' using errcode = 'P0001';
  end if;

  insert into public.transactions (
    address,
    centris_number,
    type,
    broker,
    price,
    promise_date,
    status,
    general_notes,
    creation_key
  ) values (
    trim(p_values->>'address'),
    trim(coalesce(p_values->>'centris_number', '')),
    p_values->>'type',
    (p_values->>'broker')::public.broker_assignment,
    nullif(p_values->>'price', '')::numeric,
    nullif(p_values->>'promise_date', '')::date,
    p_values->>'status',
    trim(coalesce(p_values->>'general_notes', '')),
    p_creation_key
  )
  on conflict (creation_key) where creation_key is not null do nothing
  returning * into v_transaction;

  if not found then
    select * into v_transaction
    from public.transactions
    where creation_key = p_creation_key;
    if not found then
      raise exception 'Transaction idempotente introuvable.' using errcode = 'P0001';
    end if;
    return v_transaction;
  end if;

  insert into public.transaction_contacts (transaction_id, contact_id)
  select v_transaction.id, requested.contact_id
  from (
    select distinct requested_id as contact_id
    from unnest(coalesce(p_contact_ids, array[]::uuid[])) as requested(requested_id)
  ) as requested;

  return v_transaction;
end;
$function$
CREATE OR REPLACE FUNCTION public.update_transaction_with_contacts(p_transaction_id uuid, p_values jsonb, p_contact_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_transaction public.transactions;
begin
  select * into v_transaction
  from public.transactions
  where id = p_transaction_id
  for update;

  if not found then
    raise exception 'Transaction introuvable.' using errcode = 'P0001';
  end if;
  if v_transaction.sale_finalized_at is not null
    or v_transaction.purchase_finalized_at is not null then
    raise exception 'Une transaction finalisée ne peut plus être modifiée.' using errcode = 'P0001';
  end if;
  if p_values is null or jsonb_typeof(p_values) <> 'object' then
    raise exception 'Valeurs de Transaction invalides.' using errcode = 'P0001';
  end if;
  if exists (
    select 1
    from jsonb_object_keys(p_values) as supplied(field_name)
    where supplied.field_name not in (
      'address', 'centris_number', 'type', 'broker', 'price',
      'promise_date', 'status', 'general_notes'
    )
  ) then
    raise exception 'Champ de Transaction non autorisé.' using errcode = 'P0001';
  end if;
  if p_values ? 'address' and (
    jsonb_typeof(p_values->'address') <> 'string'
    or length(trim(p_values->>'address')) = 0
  ) then
    raise exception 'Adresse de Transaction invalide.' using errcode = 'P0001';
  end if;
  if p_values ? 'type' and p_values->>'type' not in ('purchase', 'sale') then
    raise exception 'Type de Transaction invalide.' using errcode = 'P0001';
  end if;
  if p_values ? 'broker' and p_values->>'broker' not in ('france', 'maxime', 'sandrine') then
    raise exception 'Courtier de Transaction invalide.' using errcode = 'P0001';
  end if;
  if p_values ? 'status' and p_values->>'status' not in (
    'new', 'pa_preparation', 'pa_sent', 'pa_accepted', 'inspection',
    'financing', 'other_conditions', 'conditions_met', 'notary',
    'completed', 'cancelled', 'on_market', 'offer_received', 'negotiation'
  ) then
    raise exception 'Statut de Transaction invalide.' using errcode = 'P0001';
  end if;
  if p_values ? 'price' and jsonb_typeof(p_values->'price') not in ('number', 'null') then
    raise exception 'Prix de Transaction invalide.' using errcode = 'P0001';
  end if;
  if p_values ? 'promise_date'
    and jsonb_typeof(p_values->'promise_date') not in ('string', 'null') then
    raise exception 'Date de promesse invalide.' using errcode = 'P0001';
  end if;
  if p_contact_ids is not null and exists (
    select 1
    from (
      select distinct requested.contact_id
      from unnest(p_contact_ids) as requested(contact_id)
    ) as requested
    left join public.contacts as contact on contact.id = requested.contact_id
    where requested.contact_id is null or contact.id is null
  ) then
    raise exception 'Contact lié invalide.' using errcode = 'P0001';
  end if;

  if p_values <> '{}'::jsonb then
    update public.transactions
    set
      address = case when p_values ? 'address' then trim(p_values->>'address') else address end,
      centris_number = case when p_values ? 'centris_number' then trim(coalesce(p_values->>'centris_number', '')) else centris_number end,
      type = case when p_values ? 'type' then p_values->>'type' else type end,
      broker = case when p_values ? 'broker' then (p_values->>'broker')::public.broker_assignment else broker end,
      price = case when p_values ? 'price' then nullif(p_values->>'price', '')::numeric else price end,
      promise_date = case when p_values ? 'promise_date' then nullif(p_values->>'promise_date', '')::date else promise_date end,
      status = case when p_values ? 'status' then p_values->>'status' else status end,
      general_notes = case when p_values ? 'general_notes' then trim(coalesce(p_values->>'general_notes', '')) else general_notes end
    where id = p_transaction_id
    returning * into v_transaction;
  end if;

  if p_contact_ids is not null then
    delete from public.transaction_contacts
    where transaction_id = p_transaction_id;

    insert into public.transaction_contacts (transaction_id, contact_id)
    select p_transaction_id, requested.contact_id
    from (
      select distinct requested_id as contact_id
      from unnest(p_contact_ids) as requested(requested_id)
    ) as requested;
  end if;

  return v_transaction;
end;
$function$
CREATE OR REPLACE FUNCTION public.update_contact_with_addresses(p_contact_id uuid, p_values jsonb, p_addresses jsonb DEFAULT NULL::jsonb)
 RETURNS contacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_contact public.contacts;
  v_result public.contacts;
  v_next_broker public.broker_assignment;
  v_client_provenance text;
begin
  select * into v_contact
  from public.contacts
  where id = p_contact_id
  for update;

  if not found then
    raise exception 'Contact introuvable.' using errcode = 'P0002';
  end if;

  if p_values is null or jsonb_typeof(p_values) <> 'object' then
    raise exception 'Données du Contact invalides.' using errcode = '22023';
  end if;

  if p_addresses is not null and jsonb_typeof(p_addresses) <> 'array' then
    raise exception 'Adresses invalides.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(p_values) as fields(field)
    where fields.field <> all (array[
      'first_name', 'last_name', 'phone', 'email', 'birth_date',
      'mortgage_renewal_date', 'broker', 'client_type',
      'client_provenance', 'priority', 'status'
    ])
  ) then
    raise exception 'Champ Contact non autorisé.' using errcode = '22023';
  end if;

  if p_values ? 'broker' then
    if coalesce(p_values->>'broker', '') not in ('france', 'maxime', 'sandrine', 'unassigned') then
      raise exception 'Courtier invalide.' using errcode = '22023';
    end if;
    v_next_broker := (p_values->>'broker')::public.broker_assignment;
  else
    v_next_broker := v_contact.broker;
  end if;

  if p_values ? 'client_type'
     and nullif(trim(p_values->>'client_type'), '') is not null
     and p_values->>'client_type' not in ('buyer', 'seller', 'buyer_seller') then
    raise exception 'Type de client invalide.' using errcode = '22023';
  end if;

  if p_values ? 'client_provenance' then
    v_client_provenance := nullif(trim(p_values->>'client_provenance'), '');
    if v_client_provenance is not null
       and v_client_provenance not in ('friend_family', 'referral', 'prospecting', 'confia') then
      raise exception 'Provenance du client invalide.' using errcode = '22023';
    end if;
  else
    v_client_provenance := v_contact.client_provenance;
  end if;

  if p_values ? 'priority'
     and nullif(trim(p_values->>'priority'), '') is not null
     and p_values->>'priority' not in ('hot', 'warm', 'cold') then
    raise exception 'Priorité invalide.' using errcode = '22023';
  end if;

  if p_values ? 'status'
     and coalesce(p_values->>'status', '') not in ('active', 'inactive') then
    raise exception 'Statut invalide.' using errcode = '22023';
  end if;

  if coalesce(case when p_values ? 'first_name' then trim(p_values->>'first_name') else v_contact.first_name end, '') = ''
     and coalesce(case when p_values ? 'last_name' then trim(p_values->>'last_name') else v_contact.last_name end, '') = ''
     and coalesce(case when p_values ? 'phone' then trim(p_values->>'phone') else v_contact.phone end, '') = ''
     and coalesce(case when p_values ? 'email' then trim(p_values->>'email') else v_contact.email end, '') = '' then
    raise exception 'Ajoutez au minimum un nom, un téléphone ou un email.' using errcode = '22023';
  end if;

  update public.contacts
  set
    first_name = case when p_values ? 'first_name' then coalesce(trim(p_values->>'first_name'), '') else first_name end,
    last_name = case when p_values ? 'last_name' then coalesce(trim(p_values->>'last_name'), '') else last_name end,
    phone = case when p_values ? 'phone' then coalesce(trim(p_values->>'phone'), '') else phone end,
    email = case when p_values ? 'email' then coalesce(trim(p_values->>'email'), '') else email end,
    birth_date = case when p_values ? 'birth_date' then nullif(trim(p_values->>'birth_date'), '')::date else birth_date end,
    mortgage_renewal_date = case when p_values ? 'mortgage_renewal_date' then nullif(trim(p_values->>'mortgage_renewal_date'), '')::date else mortgage_renewal_date end,
    broker = v_next_broker,
    client_type = case when p_values ? 'client_type' then nullif(trim(p_values->>'client_type'), '')::public.client_type else client_type end,
    client_provenance = v_client_provenance,
    priority = case when p_values ? 'priority' then nullif(trim(p_values->>'priority'), '')::public.contact_priority else priority end,
    status = case when p_values ? 'status' then (p_values->>'status')::public.contact_status else status end,
    google_calendar_sync_status = case
      when broker is distinct from v_next_broker then 'pending'::public.calendar_sync_status
      else google_calendar_sync_status
    end,
    google_calendar_last_error = case
      when broker is distinct from v_next_broker then null
      else google_calendar_last_error
    end
  where id = p_contact_id
  returning * into v_result;

  if p_addresses is not null then
    select * into v_result
    from public.save_contact_addresses(p_contact_id, p_addresses);
  end if;

  return v_result;
end;
$function$
CREATE OR REPLACE FUNCTION public.create_manual_contact_with_addresses(p_values jsonb, p_addresses jsonb, p_creation_key uuid)
 RETURNS contacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_contact public.contacts;
  v_broker public.broker_assignment;
  v_client_type public.client_type;
  v_client_provenance text;
  v_priority public.contact_priority;
  v_status public.contact_status;
begin
  if p_creation_key is null then
    raise exception 'Clé de création requise.' using errcode = '22023';
  end if;

  select * into v_contact
  from public.contacts
  where creation_key = p_creation_key;

  if found then
    return v_contact;
  end if;

  if p_values is null or jsonb_typeof(p_values) <> 'object' then
    raise exception 'Données du Contact invalides.' using errcode = '22023';
  end if;

  if p_addresses is null or jsonb_typeof(p_addresses) <> 'array' then
    raise exception 'Adresses invalides.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(p_values) as fields(field)
    where fields.field <> all (array[
      'first_name', 'last_name', 'phone', 'email', 'birth_date',
      'mortgage_renewal_date', 'broker', 'client_type',
      'client_provenance', 'priority', 'status'
    ])
  ) then
    raise exception 'Champ Contact non autorisé.' using errcode = '22023';
  end if;

  if coalesce(trim(p_values->>'first_name'), '') = ''
     and coalesce(trim(p_values->>'last_name'), '') = ''
     and coalesce(trim(p_values->>'phone'), '') = ''
     and coalesce(trim(p_values->>'email'), '') = '' then
    raise exception 'Ajoutez au minimum un nom, un téléphone ou un email.' using errcode = '22023';
  end if;

  if coalesce(p_values->>'broker', '') not in ('france', 'maxime', 'sandrine') then
    raise exception 'Courtier invalide.' using errcode = '22023';
  end if;
  v_broker := (p_values->>'broker')::public.broker_assignment;

  if nullif(trim(p_values->>'client_type'), '') is not null
     and p_values->>'client_type' not in ('buyer', 'seller', 'buyer_seller') then
    raise exception 'Type de client invalide.' using errcode = '22023';
  end if;
  v_client_type := nullif(trim(p_values->>'client_type'), '')::public.client_type;

  v_client_provenance := nullif(trim(p_values->>'client_provenance'), '');
  if v_client_provenance is not null
     and v_client_provenance not in ('friend_family', 'referral', 'prospecting', 'confia') then
    raise exception 'Provenance du client invalide.' using errcode = '22023';
  end if;

  if nullif(trim(p_values->>'priority'), '') is not null
     and p_values->>'priority' not in ('hot', 'warm', 'cold') then
    raise exception 'Priorité invalide.' using errcode = '22023';
  end if;
  v_priority := nullif(trim(p_values->>'priority'), '')::public.contact_priority;

  if coalesce(nullif(trim(p_values->>'status'), ''), 'active') not in ('active', 'inactive') then
    raise exception 'Statut invalide.' using errcode = '22023';
  end if;
  v_status := coalesce(nullif(trim(p_values->>'status'), ''), 'active')::public.contact_status;

  insert into public.contacts (
    first_name,
    last_name,
    phone,
    email,
    birth_date,
    mortgage_renewal_date,
    broker,
    client_type,
    client_provenance,
    priority,
    status,
    source,
    creation_key
  ) values (
    coalesce(trim(p_values->>'first_name'), ''),
    coalesce(trim(p_values->>'last_name'), ''),
    coalesce(trim(p_values->>'phone'), ''),
    coalesce(trim(p_values->>'email'), ''),
    nullif(trim(p_values->>'birth_date'), '')::date,
    nullif(trim(p_values->>'mortgage_renewal_date'), '')::date,
    v_broker,
    v_client_type,
    v_client_provenance,
    v_priority,
    v_status,
    'manual',
    p_creation_key
  )
  on conflict (creation_key) where creation_key is not null do nothing
  returning * into v_contact;

  if v_contact.id is null then
    select * into v_contact
    from public.contacts
    where creation_key = p_creation_key;
    return v_contact;
  end if;

  select * into v_contact
  from public.save_contact_addresses(v_contact.id, p_addresses);

  return v_contact;
end;
$function$
CREATE OR REPLACE FUNCTION public.add_contact_note(p_contact_id uuid, p_content text, p_created_by broker_assignment, p_created_at timestamp with time zone DEFAULT now())
 RETURNS client_notes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_contact public.contacts;
  v_author public.broker_assignment;
  v_content text;
  v_created_at timestamptz;
  v_note public.client_notes;
begin
  select * into v_contact
  from public.contacts
  where id = p_contact_id
  for update;

  if not found then
    raise exception 'Contact introuvable.' using errcode = 'P0002';
  end if;

  v_content := trim(coalesce(p_content, ''));
  if v_content = '' then
    raise exception 'Le contenu de la note est requis.' using errcode = '22023';
  end if;
  if char_length(v_content) > 10000 then
    raise exception 'La note ne peut pas dépasser 10000 caractères.' using errcode = '22023';
  end if;

  v_author := case
    when p_created_by in ('france', 'maxime', 'sandrine') then p_created_by
    when v_contact.broker in ('france', 'maxime', 'sandrine') then v_contact.broker
    else null
  end;
  if v_author is null then
    raise exception 'Un courtier doit être attribué avant d’ajouter une note.' using errcode = '22023';
  end if;

  v_created_at := coalesce(p_created_at, now());
  insert into public.client_notes (
    contact_id,
    content,
    created_at,
    created_by,
    created_by_user_id
  ) values (
    p_contact_id,
    v_content,
    v_created_at,
    v_author,
    null
  )
  returning * into v_note;

  update public.contacts
  set last_contact_date = v_created_at
  where id = p_contact_id;

  return v_note;
end;
$function$
CREATE OR REPLACE FUNCTION public.merge_contacts_with_contact_dates(p_target_id uuid, p_source_id uuid, p_addresses jsonb, p_first_name text, p_last_name text, p_phone text, p_email text, p_birth_date date, p_mortgage_renewal_date date, p_civic_number text, p_address text, p_apartment text, p_city text, p_province text, p_postal_code text, p_country text, p_broker broker_assignment, p_client_type client_type, p_client_provenance text, p_priority contact_priority, p_status contact_status, p_next_follow_up_date date, p_google_event_id text, p_google_event_broker broker_assignment, p_merged_by_user_id uuid)
 RETURNS contacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_source public.contacts;
  v_target public.contacts;
  v_result public.contacts;
  v_last_contact timestamptz;
  v_addresses jsonb;
begin
  if p_target_id is null or p_source_id is null or p_target_id = p_source_id then
    raise exception 'Les contacts à fusionner doivent être différents.' using errcode = '22023';
  end if;

  perform contact.id
  from public.contacts as contact
  where contact.id in (p_target_id, p_source_id)
  order by contact.id
  for update;

  select * into v_target from public.contacts where id = p_target_id;
  select * into v_source from public.contacts where id = p_source_id;
  if v_target.id is null or v_source.id is null then
    raise exception 'Contact de fusion introuvable.' using errcode = 'P0002';
  end if;

  if p_addresses is null or jsonb_typeof(p_addresses) <> 'array' then
    raise exception 'Adresses de fusion invalides.' using errcode = '22023';
  end if;
  if p_client_provenance is not null
     and p_client_provenance not in ('friend_family', 'referral', 'prospecting', 'confia') then
    raise exception 'Provenance du client invalide.' using errcode = '22023';
  end if;

  update public.client_notes
  set contact_id = p_target_id
  where contact_id = p_source_id;

  insert into public.transaction_contacts (transaction_id, contact_id)
  select transaction_id, p_target_id
  from public.transaction_contacts
  where contact_id = p_source_id
  on conflict do nothing;

  delete from public.transaction_contacts
  where contact_id = p_source_id;

  insert into public.listing_contacts (listing_id, contact_id, role, created_at)
  select listing_id, p_target_id, role, created_at
  from public.listing_contacts
  where contact_id = p_source_id
  on conflict do nothing;

  delete from public.listing_contacts
  where contact_id = p_source_id;

  insert into public.custom_email_campaign_contacts (campaign_id, contact_id, created_at)
  select campaign_id, p_target_id, created_at
  from public.custom_email_campaign_contacts
  where contact_id = p_source_id
  on conflict do nothing;

  delete from public.custom_email_campaign_contacts
  where contact_id = p_source_id;

  update public.automatic_email_deliveries
  set contact_id = p_target_id
  where contact_id = p_source_id;

  select max(created_at) into v_last_contact
  from public.client_notes
  where contact_id = p_target_id;

  update public.contacts
  set
    first_name = trim(coalesce(p_first_name, '')),
    last_name = trim(coalesce(p_last_name, '')),
    phone = trim(coalesce(p_phone, '')),
    email = trim(coalesce(p_email, '')),
    birth_date = p_birth_date,
    mortgage_renewal_date = p_mortgage_renewal_date,
    civic_number = trim(coalesce(p_civic_number, '')),
    address = trim(coalesce(p_address, '')),
    apartment = trim(coalesce(p_apartment, '')),
    city = trim(coalesce(p_city, '')),
    province = trim(coalesce(p_province, '')),
    postal_code = trim(coalesce(p_postal_code, '')),
    country = trim(coalesce(p_country, '')),
    broker = p_broker,
    client_type = p_client_type,
    client_provenance = p_client_provenance,
    priority = p_priority,
    status = p_status,
    last_contact_date = greatest(v_target.last_contact_date, v_source.last_contact_date, v_last_contact),
    next_follow_up_date = p_next_follow_up_date,
    google_calendar_event_id = p_google_event_id,
    google_calendar_event_broker = p_google_event_broker,
    google_calendar_sync_status = case
      when p_next_follow_up_date is null then 'synced'::public.calendar_sync_status
      else 'pending'::public.calendar_sync_status
    end,
    google_calendar_last_error = null
  where id = p_target_id
  returning * into v_result;

  v_addresses := p_addresses;
  if jsonb_array_length(v_addresses) = 0 then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'civic_number', contact_address.civic_number,
          'address', contact_address.address,
          'apartment', contact_address.apartment,
          'city', contact_address.city,
          'province', contact_address.province,
          'postal_code', contact_address.postal_code,
          'country', contact_address.country,
          'is_primary', contact_address.contact_id = p_target_id and contact_address.is_primary,
          'label', case
            when contact_address.contact_id = p_target_id and contact_address.is_primary then 'Principale'
            else 'Ancienne adresse'
          end
        )
        order by (contact_address.contact_id = p_target_id and contact_address.is_primary) desc,
          contact_address.created_at desc,
          contact_address.id
      ),
      '[]'::jsonb
    ) into v_addresses
    from public.contact_addresses as contact_address
    where contact_address.contact_id in (p_target_id, p_source_id);
  end if;

  if jsonb_array_length(v_addresses) > 0 then
    select * into v_result
    from public.save_contact_addresses(p_target_id, v_addresses);
  end if;

  insert into public.contact_merges (
    merged_into_contact_id,
    merged_from,
    merged_by_user_id
  ) values (
    p_target_id,
    to_jsonb(v_source),
    p_merged_by_user_id
  );

  delete from public.contacts
  where id = p_source_id;

  return v_result;
end;
$function$
CREATE OR REPLACE FUNCTION public.merge_draft_into_contact_with_addresses(p_target_id uuid, p_values jsonb, p_addresses jsonb, p_incoming_draft jsonb, p_merged_by_user_id uuid)
 RETURNS contacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_target public.contacts;
  v_result public.contacts;
  v_client_provenance text;
  v_broker public.broker_assignment;
  v_next_follow_up_date date;
begin
