  from public.contacts
  where id = p_target_id
  for update;

  if not found then
    raise exception 'Contact introuvable.' using errcode = 'P0002';
  end if;
  if p_values is null or jsonb_typeof(p_values) <> 'object' then
    raise exception 'Valeurs de fusion invalides.' using errcode = '22023';
  end if;
  if p_addresses is null or jsonb_typeof(p_addresses) <> 'array' then
    raise exception 'Adresses de fusion invalides.' using errcode = '22023';
  end if;
  if p_incoming_draft is null or jsonb_typeof(p_incoming_draft) <> 'object' then
    raise exception 'Contact importé invalide.' using errcode = '22023';
  end if;

  v_client_provenance := nullif(trim(p_values->>'clientProvenance'), '');
  if v_client_provenance is not null
     and v_client_provenance not in ('friend_family', 'referral', 'prospecting', 'confia') then
    raise exception 'Provenance du client invalide.' using errcode = '22023';
  end if;
  if coalesce(p_values->>'broker', '') not in ('france', 'maxime', 'sandrine', 'unassigned') then
    raise exception 'Courtier invalide.' using errcode = '22023';
  end if;
  if nullif(trim(p_values->>'clientType'), '') is not null
     and p_values->>'clientType' not in ('buyer', 'seller', 'buyer_seller') then
    raise exception 'Type de client invalide.' using errcode = '22023';
  end if;
  if nullif(trim(p_values->>'priority'), '') is not null
     and p_values->>'priority' not in ('hot', 'warm', 'cold') then
    raise exception 'Priorité invalide.' using errcode = '22023';
  end if;
  if coalesce(p_values->>'status', '') not in ('active', 'inactive') then
    raise exception 'Statut invalide.' using errcode = '22023';
  end if;

  v_broker := (p_values->>'broker')::public.broker_assignment;
  v_next_follow_up_date := nullif(trim(p_values->>'nextFollowUpDate'), '')::date;

  update public.contacts
  set
    first_name = trim(coalesce(p_values->>'firstName', '')),
    last_name = trim(coalesce(p_values->>'lastName', '')),
    phone = trim(coalesce(p_values->>'phone', '')),
    email = trim(coalesce(p_values->>'email', '')),
    birth_date = nullif(trim(p_values->>'birthDate'), '')::date,
    mortgage_renewal_date = nullif(trim(p_values->>'mortgageRenewalDate'), '')::date,
    broker = v_broker,
    client_type = nullif(trim(p_values->>'clientType'), '')::public.client_type,
    client_provenance = v_client_provenance,
    priority = nullif(trim(p_values->>'priority'), '')::public.contact_priority,
    status = (p_values->>'status')::public.contact_status,
    next_follow_up_date = v_next_follow_up_date,
    google_calendar_sync_status = case
      when v_target.broker is distinct from v_broker
        or v_target.next_follow_up_date is distinct from v_next_follow_up_date
        or v_target.google_calendar_event_id is not null
      then 'pending'::public.calendar_sync_status
      else v_target.google_calendar_sync_status
    end,
    google_calendar_last_error = null
  where id = p_target_id
  returning * into v_result;

  select * into v_result
  from public.save_contact_addresses(p_target_id, p_addresses);

  insert into public.contact_merges (
    merged_into_contact_id,
    merged_from,
    merged_by_user_id
  ) values (
    p_target_id,
    p_incoming_draft,
    p_merged_by_user_id
  );

  return v_result;
end;
$function$
CREATE OR REPLACE FUNCTION public.create_transaction_with_agenda(p_values jsonb, p_contact_ids uuid[], p_creation_key uuid, p_deadlines jsonb)
 RETURNS transactions
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_transaction public.transactions;
  v_deadline jsonb;
  v_field text;
  v_date date;
begin
  if p_creation_key is null then
    raise exception 'Clé de création requise.' using errcode = '22023';
  end if;
  -- Serialize retries of a dossier, including its entire agenda.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_creation_key::text, 7219));
  select * into v_transaction from public.transactions where creation_key = p_creation_key;
  if found then return v_transaction; end if;

  if p_deadlines is null or jsonb_typeof(p_deadlines) <> 'array' then
    raise exception 'Échéances invalides.' using errcode = '22023';
  end if;
  if jsonb_array_length(p_deadlines) > 100 then
    raise exception 'Trop d’échéances.' using errcode = '22023';
  end if;

  -- Validate all entries before creating anything. Errors from inserts also roll back everything.
  for v_deadline in select value from jsonb_array_elements(p_deadlines) loop
    if jsonb_typeof(v_deadline) <> 'object' then
      raise exception 'Échéance invalide.' using errcode = '22023';
    end if;
    if exists (select 1 from jsonb_object_keys(v_deadline) as f(k) where k not in (
      'title', 'due_date', 'due_time', 'source_type', 'source_document',
      'source_form', 'source_section', 'source_text', 'source_confidence'
    )) then
      raise exception 'Champ d’échéance non autorisé.' using errcode = '22023';
    end if;
    if coalesce(jsonb_typeof(v_deadline->'title'), '') <> 'string'
      or length(trim(v_deadline->>'title')) not between 1 and 300
      or coalesce(jsonb_typeof(v_deadline->'due_date'), '') <> 'string'
      or coalesce(v_deadline->>'due_date', '') !~ '^\d{4}-\d{2}-\d{2}$'
      or coalesce(v_deadline->>'source_type', '') not in ('manual', 'oaciq') then
      raise exception 'Titre, date ou source invalide.' using errcode = '22023';
    end if;
    v_date := (v_deadline->>'due_date')::date;
    if v_date < date '1900-01-01' or v_date > date '2200-12-31'
      or to_char(v_date, 'YYYY-MM-DD') <> v_deadline->>'due_date' then
      raise exception 'Date d’échéance invalide.' using errcode = '22023';
    end if;
    if v_deadline->>'due_time' is not null and (
      jsonb_typeof(v_deadline->'due_time') <> 'string'
      or v_deadline->>'due_time' !~ '^([01]\d|2[0-3]):[0-5]\d$'
    ) then
      raise exception 'Heure d’échéance invalide.' using errcode = '22023';
    end if;
    foreach v_field in array array['source_document', 'source_form', 'source_section', 'source_text', 'source_confidence'] loop
      if v_deadline ? v_field and jsonb_typeof(v_deadline->v_field) not in ('string', 'null') then
        raise exception 'Provenance d’échéance invalide.' using errcode = '22023';
      end if;
    end loop;
    if length(coalesce(v_deadline->>'source_document', '')) > 255
      or length(coalesce(v_deadline->>'source_form', '')) > 100
      or length(coalesce(v_deadline->>'source_section', '')) > 100
      or length(coalesce(v_deadline->>'source_text', '')) > 20000
      or (v_deadline->>'source_confidence' is not null and v_deadline->>'source_confidence' not in ('high', 'medium', 'low')) then
      raise exception 'Provenance d’échéance invalide.' using errcode = '22023';
    end if;
  end loop;

  select * into v_transaction from public.create_transaction_with_contacts(p_values, p_contact_ids, p_creation_key);
  insert into public.transaction_deadlines (
    transaction_id, title, due_date, due_time, completed,
    source_type, source_document, source_form, source_section, source_text, source_confidence,
    google_calendar_sync_status, google_calendar_event_id, google_calendar_event_broker
  )
  select v_transaction.id, trim(d->>'title'), (d->>'due_date')::date,
    (d->>'due_time')::time, false, d->>'source_type',
    case when d->>'source_type' = 'oaciq' then d->>'source_document' end,
    case when d->>'source_type' = 'oaciq' then d->>'source_form' end,
    case when d->>'source_type' = 'oaciq' then d->>'source_section' end,
    case when d->>'source_type' = 'oaciq' then d->>'source_text' end,
    case when d->>'source_type' = 'oaciq' then d->>'source_confidence' end,
    'synced'::public.calendar_sync_status, null, null
  from jsonb_array_elements(p_deadlines) as deadlines(d);
  return v_transaction;
end;
$function$
CREATE OR REPLACE FUNCTION public.check_mortgage_referral_broker()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.transactions where id = new.transaction_id and broker = new.broker for share) then
    raise exception 'Le courtier de la référence doit correspondre à la transaction.' using errcode = '23514';
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.protect_mortgage_referral_broker()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.broker is distinct from old.broker and exists (
    select 1 from public.mortgage_referrals where transaction_id = old.id
  ) then
    raise exception 'Supprimez les références hypothécaires avant de changer le courtier.' using errcode = '23514';
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.claim_birthday_greeting(p_contact_id uuid, p_occurrence date, p_action text, p_actor text)
 RETURNS SETOF contact_birthday_greetings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare c public.contacts; g public.contact_birthday_greetings; v_today date := (now() at time zone 'America/Toronto')::date;
  v_birthday date; v_status text;
begin
  if p_action not in ('done','manual','auto') or p_occurrence<>v_today then return; end if;
  select * into c from public.contacts where id=p_contact_id for update;
  if not found or c.birth_date is null then return; end if;
  -- Last day of February observes leap-day birthdays in non-leap years.
  v_birthday := make_date(extract(year from v_today)::int,extract(month from c.birth_date)::int,1);
  v_birthday := v_birthday + (least(extract(day from c.birth_date)::int,extract(day from (v_birthday + interval '1 month - 1 day'))::int)-1);
  if v_birthday<>v_today then return; end if;
  if p_action='auto' and ((now() at time zone 'America/Toronto')::time < time '17:00'
    or not exists(select 1 from public.automatic_email_rules where rule_type='birthday' and trigger_config @> '{"birthdayFallbackEnabled":true}')) then return; end if;
  select * into g from public.contact_birthday_greetings where contact_id=p_contact_id and occurrence_date=p_occurrence;
  if found and (g.status<>'failed' or (p_action='auto' and g.automatic_attempted_at is not null)) then return; end if;
  v_status := case p_action when 'done' then 'manual_done' when 'manual' then 'manual_sending' else 'auto_sending' end;
  return query insert into public.contact_birthday_greetings(contact_id,occurrence_date,status,acted_by,automatic_attempted_at,completed_at)
  values(p_contact_id,p_occurrence,v_status,p_actor,case when p_action='auto' then now() end,case when p_action='done' then now() end)
  on conflict(contact_id,occurrence_date) do update set status=v_status,acted_by=p_actor,attempt_token=gen_random_uuid(),error_message=null,
    automatic_attempted_at=coalesce(contact_birthday_greetings.automatic_attempted_at,excluded.automatic_attempted_at),completed_at=excluded.completed_at
  returning *;
end;
$function$
CREATE OR REPLACE FUNCTION public.update_birthday_rule(p_id uuid, p_values jsonb, p_enabled boolean DEFAULT NULL::boolean)
 RETURNS SETOF automatic_email_rules
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_rule public.automatic_email_rules; v_enabled boolean; v_subject text; v_body text;
begin
  select * into v_rule from public.automatic_email_rules where id=p_id and rule_type='birthday' for update;
  if not found then return; end if;
  v_enabled := coalesce(p_enabled,(v_rule.trigger_config->>'birthdayFallbackEnabled')::boolean,false);
  v_subject := coalesce(p_values->>'subject_template',v_rule.subject_template);
  v_body := coalesce(p_values->>'body_template',v_rule.body_template);
  if v_enabled and (
    (case when p_values ? 'default_broker' then p_values->>'default_broker' else v_rule.default_broker::text end) is null
    or trim(v_subject)='' or trim(v_body)=''
    or regexp_replace(v_subject || v_body,'\{\{\s*(firstName|lastName|fullName)\s*\}\}','','g') ~ '(\{\{|\}\})'
  ) then raise exception 'Configuration Bonne fête incomplète'; end if;
  return query update public.automatic_email_rules r set
    name=coalesce(p_values->>'name',r.name),
    execution_mode=coalesce(p_values->>'execution_mode',r.execution_mode),
    send_hour=17,send_minute=0,
    status=coalesce(p_values->>'status',r.status),
    default_broker=case when p_values ? 'default_broker' then (p_values->>'default_broker')::public.broker_assignment else r.default_broker end,
    subject_template=coalesce(p_values->>'subject_template',r.subject_template),
    body_template=coalesce(p_values->>'body_template',r.body_template),
    trigger_config=jsonb_set(r.trigger_config,'{birthdayFallbackEnabled}',coalesce(to_jsonb(p_enabled),r.trigger_config->'birthdayFallbackEnabled','false'::jsonb))
  where r.id=p_id and r.rule_type='birthday' returning r.*;
end $function$
CREATE OR REPLACE FUNCTION public.invoke_birthday_scheduler()
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_secret text; v_request bigint;
begin
  select decrypted_secret into v_secret from vault.decrypted_secrets where name='crm_birthday_cron_secret';
  if v_secret is null then return null; end if;
  select net.http_get(
    url:='https://crm-eight-beryl-72.vercel.app/api/cron/birthday-greetings',
    headers:=jsonb_build_object('Authorization','Bearer '||v_secret),
    timeout_milliseconds:=120000
  ) into v_request;
  return v_request;
end $function$
CREATE OR REPLACE FUNCTION public.claim_purchase_anniversary_greeting(p_transaction_id uuid, p_contact_id uuid, p_occurrence date, p_action text, p_actor text)
 RETURNS SETOF purchase_anniversary_greetings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare t public.transactions; c public.contacts; g public.purchase_anniversary_greetings; v_today date := (now() at time zone 'America/Toronto')::date;
  v_birthday date; v_status text;
begin
  if p_action not in ('done','manual','auto') or p_occurrence<>v_today then return; end if;
  select * into t from public.transactions where id=p_transaction_id for update;
  if not found or t.type<>'purchase' or t.purchase_finalized_at is null or t.notary_date is null
    or extract(year from t.notary_date)>=extract(year from v_today) then return; end if;
  select * into c from public.contacts where id=p_contact_id for update;
  if not found then return; end if;
  perform 1 from public.transaction_contacts where transaction_id=p_transaction_id and contact_id=p_contact_id for update;
  if not found then return; end if;
  -- Last day of February observes leap-day birthdays in non-leap years.
  v_birthday := make_date(extract(year from v_today)::int,extract(month from t.notary_date)::int,1);
  v_birthday := v_birthday + (least(extract(day from t.notary_date)::int,extract(day from (v_birthday + interval '1 month - 1 day'))::int)-1);
  if v_birthday<>v_today then return; end if;
  if p_action='auto' and ((now() at time zone 'America/Toronto')::time < time '17:00'
    or not exists(select 1 from public.automatic_email_rules where rule_type='purchase_anniversary' and trigger_config @> '{"purchaseAnniversaryFallbackEnabled":true}')) then return; end if;
  select * into g from public.purchase_anniversary_greetings where transaction_id=p_transaction_id and contact_id=p_contact_id and occurrence_date=p_occurrence;
  if found and (g.status<>'failed' or (p_action='auto' and g.automatic_attempted_at is not null)) then return; end if;
  v_status := case p_action when 'done' then 'manual_done' when 'manual' then 'manual_sending' else 'auto_sending' end;
  return query insert into public.purchase_anniversary_greetings(transaction_id,contact_id,occurrence_date,status,acted_by,automatic_attempted_at,completed_at)
  values(p_transaction_id,p_contact_id,p_occurrence,v_status,p_actor,case when p_action='auto' then now() end,case when p_action='done' then now() end)
  on conflict(transaction_id,contact_id,occurrence_date) do update set status=v_status,acted_by=p_actor,attempt_token=gen_random_uuid(),error_message=null,
    automatic_attempted_at=coalesce(purchase_anniversary_greetings.automatic_attempted_at,excluded.automatic_attempted_at),completed_at=excluded.completed_at
  returning *;
end;
$function$
