CREATE OR REPLACE FUNCTION public.accounting_promote_invoice(p_expense uuid, p_document uuid, p_token uuid, p_actor text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  perform 1 from accounting_expenses where id=p_expense and operation_token=p_token and operation_until>now() for update;
  if not found then raise exception 'Accounting operation expired'; end if;
  perform 1 from accounting_expense_documents where id=p_document and expense_id=p_expense and state='pending';
  if not found then raise exception 'Invoice unavailable'; end if;
  update accounting_expense_documents set state='retired' where expense_id=p_expense and state='current';
  update accounting_expense_documents set state='current', uploaded_at=now() where id=p_document;
  update accounting_expenses set updated_by=p_actor, updated_at=now() where id=p_expense;
end $function$
CREATE OR REPLACE FUNCTION public.accounting_set_broker_balance(p_broker broker_assignment, p_balance numeric, p_actor text, p_expected_version integer)
 RETURNS TABLE(broker text, balance text, version integer, updated_at timestamp with time zone, updated_by text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare saved accounting_broker_balances%rowtype;
begin
  if p_broker is null or p_broker='unassigned' or p_expected_version is null or p_expected_version<0
    or p_balance is null or p_balance not between -9999999999.99 and 9999999999.99 or p_balance<>round(p_balance,2)
    or p_actor is null or not (p_actor='immoplus' or exists(select 1 from accounting_brokers() b where b.id=p_actor)) then
    raise exception 'Invalid balance fields' using errcode='22023';
  end if;
  if p_expected_version=0 then
    insert into accounting_broker_balances as b(broker,balance,updated_by)
    values(p_broker,p_balance,p_actor) on conflict on constraint accounting_broker_balances_pkey do nothing returning b.* into saved;
  else
    update accounting_broker_balances b set balance=p_balance,version=b.version+1,updated_at=clock_timestamp(),updated_by=p_actor
    where b.broker=p_broker and b.version=p_expected_version returning b.* into saved;
  end if;
  if saved.broker is null then return; end if;
  return query select saved.broker::text,saved.balance::text,saved.version,saved.updated_at,saved.updated_by;
end $function$
CREATE OR REPLACE FUNCTION public.accounting_month_date(p_month date, p_day integer)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'public'
AS $function$
  select date_trunc('month',p_month)::date +
    (least(p_day,extract(day from date_trunc('month',p_month)+interval '1 month - 1 day')::integer)-1);
$function$
CREATE OR REPLACE FUNCTION public.accounting_list_broker_balances()
 RETURNS TABLE(broker text, label text, balance text, version integer, updated_at timestamp with time zone, updated_by text)
 LANGUAGE sql
