CREATE OR REPLACE FUNCTION public.accounting_materialize_recurring_expenses(p_today date DEFAULT ((now() AT TIME ZONE 'America/Toronto'::text))::date, p_rule_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare r accounting_recurring_expenses%rowtype; due date; created integer=0; inserted integer;
begin
  if p_today is null then raise exception 'Accounting date required'; end if;
  for r in select * from accounting_recurring_expenses
    where active and next_due_date<=p_today and (p_rule_id is null or id=p_rule_id)
    order by id for update
  loop
    due=r.next_due_date;
    while due<=p_today loop
      insert into accounting_expenses(assigned_broker,category,vendor,description,amount,notes,renewal_date,expense_date,
        is_paid,paid_at,recurring_rule_id,recurring_period,created_by,updated_by)
      values(r.assigned_broker,r.category,r.vendor,r.description,r.amount,r.notes,r.renewal_date,due,
        false,null,r.id,date_trunc('month',due)::date,r.created_by,r.updated_by)
      on conflict(recurring_rule_id,recurring_period) do nothing;
      get diagnostics inserted=row_count;
      created=created+inserted;
      due=accounting_month_date((date_trunc('month',due)+interval '1 month')::date,r.day_of_month);
    end loop;
    update accounting_recurring_expenses set next_due_date=due,updated_at=now() where id=r.id;
  end loop;
  return created;
end $function$
CREATE OR REPLACE FUNCTION public.accounting_save_recurring_expense(p_expense uuid, p_fields jsonb, p_monthly boolean, p_stop_confirmed boolean, p_actor text, p_token uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare e accounting_expenses%rowtype; r accounting_recurring_expenses%rowtype;
  rid uuid; eid uuid; enabled boolean; first_date date; period date;
  assigned public.broker_assignment;
  today date=(now() at time zone 'America/Toronto')::date;
begin
  if p_actor is null or p_actor not in ('france','maxime','sandrine','immoplus') then raise exception 'Invalid accounting actor'; end if;
  if p_fields is null or jsonb_typeof(p_fields)<>'object' then raise exception 'Invalid accounting fields'; end if;
  first_date=(p_fields->>'expense_date')::date;
  if p_expense is not null then
    select * into e from accounting_expenses where id=p_expense for update;
    if not found or e.operation_token is distinct from p_token or p_token is null or e.operation_until<=now() then
      raise exception 'Accounting operation expired';
    end if;
    rid=e.recurring_rule_id; period=e.recurring_period;
    if rid is not null then select * into r from accounting_recurring_expenses where id=rid for update; end if;
  end if;
  assigned=case when p_fields ? 'assigned_broker' then nullif(p_fields->>'assigned_broker','')::public.broker_assignment else e.assigned_broker end;
  enabled=coalesce(p_monthly,r.active,false);
  if enabled and first_date is null then raise exception 'Monthly start date required'; end if;
  if rid is not null and r.active and not enabled and not coalesce(p_stop_confirmed,false) then
    raise exception 'Confirm recurrence stop';
  end if;
  if rid is null and enabled then
    insert into accounting_recurring_expenses(assigned_broker,category,vendor,description,amount,notes,renewal_date,
      day_of_month,start_date,next_due_date,created_by,updated_by)
    values(assigned,p_fields->>'category',p_fields->>'vendor',p_fields->>'description',(p_fields->>'amount')::numeric,
      coalesce(p_fields->>'notes',''),(p_fields->>'renewal_date')::date,extract(day from first_date)::smallint,
      first_date,accounting_month_date((date_trunc('month',first_date)+interval '1 month')::date,extract(day from first_date)::integer),p_actor,p_actor)
    returning id into rid;
    period=date_trunc('month',first_date)::date;
  elsif rid is not null then
    -- A stopped series resumes next month, without billing the inactive gap.
    update accounting_recurring_expenses set active=enabled,
      assigned_broker=case when enabled then assigned else assigned_broker end,
      category=case when enabled then p_fields->>'category' else category end,
      vendor=case when enabled then p_fields->>'vendor' else vendor end,
      description=case when enabled then p_fields->>'description' else description end,
      amount=case when enabled then (p_fields->>'amount')::numeric else amount end,
      notes=case when enabled then coalesce(p_fields->>'notes','') else notes end,
      renewal_date=case when enabled then (p_fields->>'renewal_date')::date else renewal_date end,
      next_due_date=case when enabled and not r.active then greatest(next_due_date,
        accounting_month_date((date_trunc('month',today)+interval '1 month')::date,day_of_month)) else next_due_date end,
      updated_by=p_actor,updated_at=now() where id=rid;
  end if;
  if p_expense is null then
    insert into accounting_expenses(assigned_broker,category,vendor,description,amount,notes,renewal_date,expense_date,
      recurring_rule_id,recurring_period,created_by,updated_by,is_paid,paid_at)
    values(assigned,p_fields->>'category',p_fields->>'vendor',p_fields->>'description',(p_fields->>'amount')::numeric,
      coalesce(p_fields->>'notes',''),(p_fields->>'renewal_date')::date,first_date,rid,period,p_actor,p_actor,false,null)
    returning id into eid;
  else
    update accounting_expenses set assigned_broker=assigned,category=p_fields->>'category',vendor=p_fields->>'vendor',
      description=p_fields->>'description',amount=(p_fields->>'amount')::numeric,notes=coalesce(p_fields->>'notes',''),
      renewal_date=(p_fields->>'renewal_date')::date,expense_date=first_date,recurring_rule_id=rid,recurring_period=period,
      updated_by=p_actor,updated_at=now() where id=p_expense;
    eid=p_expense;
  end if;
  return eid;
end $function$
CREATE OR REPLACE FUNCTION public.accounting_audit_broker_balance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  insert into accounting_broker_balance_history(broker,old_balance,new_balance,updated_at,updated_by,version)
  values(new.broker,case when tg_op='INSERT' then 0 else old.balance end,new.balance,new.updated_at,new.updated_by,new.version);
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.sign_inventory_write(p_action text, p_data jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 v_id uuid; v_old sign_assignments; v_new sign_assignments; v_stock sign_inventory_stock;
 v_before jsonb; v_after jsonb; v_address text; v_addons text[]; v_bad record; v_broker broker_assignment;
begin
 if p_actor is null or length(trim(p_actor))=0 then raise exception using errcode='P0001',message='Utilisateur requis.'; end if;
 if p_action not in ('assign','edit','return','stock') then raise exception using errcode='P0001',message='Opération invalide.'; end if;
 -- One short transaction for all stock mutations. Waiters re-read committed stock.
 perform pg_advisory_xact_lock(714203,1);
 if p_action='stock' then
   if p_data->>'id' like 'sign:%' then
     v_broker:=substring(p_data->>'id' from 6)::broker_assignment;
     insert into sign_inventory_stock(id,kind,broker,label) values(p_data->>'id','sign',v_broker,'Pancartes') on conflict do nothing;
   end if;
   select * into v_stock from sign_inventory_stock where id=p_data->>'id';
   if not found then raise exception using errcode='P0001',message='Article introuvable.'; end if;
   if v_stock.version is distinct from (p_data->>'version')::integer then raise exception using errcode='P0001',message='Inventaire modifié entre-temps. Actualisez puis réessayez.'; end if;
   if (p_data->>'total')::integer is null or (p_data->>'total')::integer not between 0 and 100000 then raise exception using errcode='P0001',message='Quantité totale invalide.'; end if;
   select * into v_bad from sign_inventory_availability() where id=v_stock.id;
   if (p_data->>'total')::integer<v_bad.used then raise exception using errcode='P0001',message=format('%s article(s) en circulation. Le total ne peut pas être inférieur à %s.',v_bad.used,v_bad.used); end if;
   update sign_inventory_stock set total=(p_data->>'total')::integer,version=version+1,updated_at=clock_timestamp(),updated_by=p_actor where id=v_stock.id;
   insert into sign_inventory_events(stock_id,action,before_data,after_data,created_by) values(v_stock.id,'stock',to_jsonb(v_stock),p_data,p_actor);
   return jsonb_build_object('id',v_stock.id);
 end if;
 v_id:=(p_data->>'id')::uuid;
 select * into v_old from sign_assignments where id=v_id;
 if p_action='assign' and found then
   -- Same operation ID is safe to retry, including after a lost HTTP response.
   return jsonb_build_object('id',v_id,'replayed',true);
 end if;
 if p_action<>'assign' then
   if v_old.id is null then raise exception using errcode='P0001',message='Attribution introuvable.'; end if;
   if p_action='return' and v_old.returned_at is not null then return jsonb_build_object('id',v_id,'replayed',true); end if;
   if v_old.returned_at is not null then raise exception using errcode='P0001',message='Ce matériel a déjà été retourné.'; end if;
   if v_old.version is distinct from (p_data->>'version')::integer then raise exception using errcode='P0001',message='Attribution modifiée entre-temps. Actualisez puis réessayez.'; end if;
   v_before:=to_jsonb(v_old)||jsonb_build_object('addons',(select coalesce(jsonb_agg(stock_id),'[]'::jsonb) from sign_assignment_addons where assignment_id=v_id));
 end if;
 if p_action='return' then
   update sign_assignments set returned_at=clock_timestamp(),returned_by=p_actor,updated_at=clock_timestamp(),updated_by=p_actor,version=version+1 where id=v_id returning * into v_new;
 else
   select concat_ws(', ',concat_ws(' ',nullif(civic_number,''),address),nullif(apartment,''),nullif(city,'')) into v_address from listings where id=(p_data->>'listing_id')::uuid;
   if not found then raise exception using errcode='P0001',message='Sélectionnez une propriété du CRM.'; end if;
   v_broker:=(p_data->>'broker')::broker_assignment;
   if v_broker is null or v_broker='unassigned' then raise exception using errcode='P0001',message='Sélectionnez un courtier.'; end if;
   select coalesce(array_agg(value),'{}'::text[]) into v_addons from jsonb_array_elements_text(p_data->'addons');
   if cardinality(v_addons)<>(select count(distinct x) from unnest(v_addons) x) or exists(select 1 from unnest(v_addons) x where not exists(select 1 from sign_inventory_stock s where s.id=x and s.kind='addon')) then raise exception using errcode='P0001',message='Ajouts invalides.'; end if;
   if nullif(p_data->>'sign_type','') is null and not coalesce((p_data->>'has_bac')::boolean,false) and cardinality(v_addons)=0 then raise exception using errcode='P0001',message='Sélectionnez au moins un article.'; end if;
   if p_action='assign' then
     insert into sign_assignments(id,listing_id,address_snapshot,broker,sign_type,has_bac,created_by,updated_by)
     values(v_id,(p_data->>'listing_id')::uuid,v_address,v_broker,nullif(p_data->>'sign_type',''),coalesce((p_data->>'has_bac')::boolean,false),p_actor,p_actor) returning * into v_new;
   else
     update sign_assignments set listing_id=(p_data->>'listing_id')::uuid,address_snapshot=v_address,broker=v_broker,sign_type=nullif(p_data->>'sign_type',''),has_bac=coalesce((p_data->>'has_bac')::boolean,false),version=version+1,updated_at=clock_timestamp(),updated_by=p_actor where id=v_id returning * into v_new;
     delete from sign_assignment_addons where assignment_id=v_id;
   end if;
   insert into sign_assignment_addons(assignment_id,stock_id) select v_id,x from unnest(v_addons) x;
   select * into v_bad from sign_inventory_availability() where available<0 limit 1;
   if found then raise exception using errcode='P0001',message=format('Stock insuffisant : %s. Actualisez les disponibilités.',v_bad.label); end if;
 end if;
 v_after:=to_jsonb(v_new)||jsonb_build_object('addons',(select coalesce(jsonb_agg(stock_id),'[]'::jsonb) from sign_assignment_addons where assignment_id=v_id));
 insert into sign_inventory_events(assignment_id,action,before_data,after_data,created_by) values(v_id,p_action,v_before,v_after,p_actor);
 return jsonb_build_object('id',v_id);
end;
$function$
CREATE OR REPLACE FUNCTION public.sign_inventory_availability()
 RETURNS TABLE(id text, kind text, broker text, label text, total integer, used bigint, available bigint, version integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
 with stocks as (
   select 'sign:'||b::text id,'sign' kind,b::text broker,initcap(b::text) label,coalesce(s.total,0) total,coalesce(s.version,0) version
   from unnest(enum_range(null::public.broker_assignment)) b left join sign_inventory_stock s on s.id='sign:'||b::text where b::text<>'unassigned'
   union all select s.id,s.kind,null::text,s.label,s.total,s.version from sign_inventory_stock s where s.kind<>'sign'
 ), counts as (
   select s.*,case when s.kind='sign' then (select count(*) from sign_assignments a where a.returned_at is null and a.broker::text=s.broker and a.sign_type is not null)
     when s.kind='bac' then (select count(*) from sign_assignments a where a.returned_at is null and a.has_bac)
     else (select count(*) from sign_assignment_addons aa join sign_assignments a on a.id=aa.assignment_id where a.returned_at is null and aa.stock_id=s.id) end used
   from stocks s
 ) select c.id,c.kind,c.broker,c.label,c.total,c.used,c.total-c.used,c.version from counts c order by c.kind,c.label;
$function$
CREATE OR REPLACE FUNCTION public.mortgage_referral_payment(p_id uuid, p_broker broker_assignment, p_amount numeric, p_date date, p_version integer, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare r public.mortgage_referrals;
begin
  if p_actor is null or p_actor not in ('maxime','france','sandrine','immoplus') then
    raise exception 'Utilisateur invalide.';
  end if;
  if p_actor not in ('maxime','immoplus') and p_actor <> p_broker::text then
    raise exception 'Ce paiement appartient à un autre courtier.';
  end if;
  if (p_amount is null) <> (p_date is null) or
     (p_amount is not null and (p_amount <= 0 or p_amount > 9999999999.99 or p_amount <> round(p_amount,2))) then
    raise exception 'Indiquez le montant réellement reçu pour confirmer le paiement.';
  end if;
  if p_date is not null and (p_date < date '1900-01-01' or p_date > date '9999-12-31') then
    raise exception 'Date du paiement invalide.';
  end if;
  select * into r from public.mortgage_referrals where id=p_id and broker=p_broker for update;
  if not found or not exists(select 1 from public.transactions where id=r.transaction_id and broker=p_broker) then
    raise exception 'Référence indisponible pour ce courtier.';
  end if;
  if r.operation_until > now() then
    raise exception 'Une opération est en cours. Réessayez.';
  end if;
  if p_version is null or r.payment_version <> p_version then
    raise exception 'Le paiement a changé. Fermez cette fenêtre et actualisez la page avant de réessayer.';
  end if;
  update public.mortgage_referrals set paid_amount=p_amount,paid_at=p_date,
    payment_updated_at=clock_timestamp(),payment_updated_by=p_actor,payment_version=payment_version+1
    where id=p_id returning * into r;
  return jsonb_build_object('id',r.id,'paid_amount',r.paid_amount,'paid_at',r.paid_at,
    'payment_updated_at',r.payment_updated_at,'payment_updated_by',r.payment_updated_by,'payment_version',r.payment_version);
end;
$function$
